(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-2"] = [{"a": [21], "v": 1, "p": 109, "ev": 1, "ep": 111, "sid": 110, "t": "قوله - عز وجل - ﴿يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ﴾⟪2:21⟫ الآية (21) - سورة البقرة.\nقد تقدم أن \" الناس \" يستعمل على وجهين أحدهما المشار به إلى الصورة المخصوصة، وذلك عام في الصغير والكبير، والعاقل وغير العاقل، والثاني المشار به إلى المختص بقوى العلم والعمل المحكم وهو المستعمل على طريق المدح، ولذلك يقال: فلان أكثر إنسانية من فلان، لاختصاص هذا المعنى بقبول الزيادة والنقصان، وهذا المعنى هو المراد في هذا الموضع، والعبادة نهاية التذلل في الخدمة وبذل الطاعة وذلك في مقابلة أعظم النعم، ولا يستحقها غير الله تعالى، فهو الذي له أعظم النهم، و \" العبادة \" تقال في ثلاثة أشياء: اعتقاد الحق، وتحري الصدق، وعمل الخير، وعبادة الله قد يكون في فعل المباحات كما يكون في أداء الواجبات وذلك إذا قصد بالفعل وجه الله وتحرى به مرضاته.\nوقد قال بعض الحكماء: \" مباحات أولياء الله كلها واجبات \" وواجباتهم نوافل \" فقيل كيف يكون ذلك؟ قال: لأنهم لا يقومون على تناول مباح لهم كالأكل والشرب حتى يضطروا إليه، فيصير تناولها متحتما ويلتزمون من الفرائض فوق ما يلزمهم حتى يصير فرضهم متنفلا، وبهذا النظر قيل\n⟦1:110⟧\nعن أكل الصالحين تنزل الرحمة تنبيها أنه لا يتناول إلا إذا اشتد به الأمر، ووجب عليه الأكل إمساكا لرمقه.\nألا ترى أن كثيرا من المحظورات يصير مباحا عند الضرورات بل ربما يصير عليه من الواجبات.\nإن قيل: ما الفرق بين قوله: ﴿وَٱعۡبُدُواْ ٱللَّهَ﴾⟪4:36⟫ وبين قوله ﴿ٱعۡبُدُواْ رَبَّكُمُ﴾⟪2:21⟫ قيل في قوله ﴿ٱعۡبُدُواْ رَبَّكُمُ﴾⟪2:21⟫ إيجاب العبادة بواسطة رؤية نعمه التي بها تربيتهم وقوامهم، وفي قوله: ﴿وَٱعۡبُدُواْ ٱللَّهَ﴾ إيجاب عبادته بمراعاته عز وجل من غير واسطة وعلى ذلك قوله: ﴿يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ﴾ وقوله ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ﴾ فحيث ذكر الناس ذكر معه الرب، وحيث ذكر الإيمان ذكر الله - لما تقدم وأما الخلق فتقدير الأعراض الجسمانية وإيجادها، وقد يقال مفيدا للتقدير من غير إيجاد نحو قوله الشاعر:\nوأراك تفري ما خلقت\n....\nوبعض القوم يخلق ثم لا يفري\nواستعمل الخلق في الأجسام والخلق في القوى والأفعال، وجعل \" خلقت \" للتكوين، وأخلقت للإفساد، نحو فريت، وأفريت، وذلك نحو \" أخلقت الثوب \" فخلق وأخلق، ولما كان الشيء الحلق كثيرا ما يلين قبل حجر أخلق و \" الصخرة خلقاء \" أي \" ملساء \"، ومن أجل أن \" الخلق لا يستعمل إلا في إيجاد الأجسام وأعراضها امتنع قوم من إطلاق الخلق على القرآن، فراعوا فيه هذا الوجه دون الوجه الآخر، قالوا: ولا يكاد يقال في وصف الكلام مخلوق ومختلق إلا إذا أريد به المنقول المفتعل.\nوعلى هذا قال تعالى حكاية عن الكفار في وصفه ﴿إِنۡ هَٰذَآ إِلَّا خُلُقُ ٱلۡأَوَّلِينَ﴾⟪26:137⟫ ولا يكاد يستعمل الخالق مطلقا إلا في وصف الله تعالى.\nوقيل في الجملة: يستعمل في المتقدم لكن ذلك على أربعة أوجه تقدم بالزمان نحو آدم قبل نوح عليهما السلام، وتقدم بالذات وهو في كل شيئين متى توهمت ارتفاع أحدهما ارتفع معه الآخر، وإذا توهمت ارتفاع الآخر لم يرتفع معه الأول، كالحياة مع العلم، وتقدم بالشرف، نحو تقدم الأمير للحاجب، وبهذا النظر استعمل العتيق في الشريف وإن كان موضوعه لما تقدم زمانه، نحو\n⟦1:111⟧\nقولنا: تمر عتيق .\nوتقدم بالرتبة الوضيعة نحو قولنا: الواحد قبل الاثنين، وقوله: \" الذين \" ها هنا يتناول نوع العقلاء وغيرهم من جميع الأشياء.\nوفي ذلك تنبيه أن الله تعالى خالقنا وخالق كل ما تقدمنا، وكل ما هو سبب في وجودنا وحصولنا من الآباء والأمكنة والأزمنة والسماء والأرض وسائر ما لو توهمناه مرتفعا لم يحصل، وأخرج الكلام مخرج المقرر عند المخاطبين أنه تعالى خالق الكل ومبدع الجميع، فعلم ذلك عندهم إما موجود وإما ممكن وجوده، ولهذا قال ﴿وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَهُمۡ لَيَقُولُنَّ ٱللَّهُۖ﴾⟪43:87⟫ ولعل ذكر بعضهم أن معنى ما في غاية القرآن، قال: لأن \" لعل \" للشك، والشك لا يصح على الله تعالى، فكما لا يصح أن يقول أرجو، وأشك وأظن، فكذلك لا يصح منه أن يقول \" لعل \" و \" عسى \" بمعنى ذلك فثبت أن معناه إذا أورده معنى ما وهذا تصور بعيد، وذاك أن القائل إذا قال: \" إفعل كذا لعلك تفلح يصح أن يكون \" لعلك \" حال للمخاطب بمعنى أنا طامع راج لفلاحك ويصح أن يكون للمخاطب بمعنى \" وأنت طامع في فلاحك \"، ولما دلت الدلالة أن الطمع إنما يكون لمن يخفى عليه العواقب، علم أنه لا يصح أن يكون لله تعالى إذا ورد في كلامه، فصار ذلك حال للمخاطب كأنه قال: \" اعبدوا ربكم راجين تقاكم \"، وإخراج الكلام على ذلك لأن من شرط المكلف أن يكون واقفا بين الرجاء والخوف ولذلك قال في مدح المؤمنين ﴿يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا﴾⟪32:16⟫ وقال: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾⟪17:57⟫ وكذلك التقوى فقد تقدم أن لها ثلاث منازل: الأولى: ترك الكفر، والثانية: ترك المحارم التي تحظرها الشريعة.\nوالثالث: حفظ الخواطر والنيات، والآخران اللذان رجانا هما الله تعالى ها هنا دون الأولى، إذ لا يصح فعل العبادة مع وجود الكفر، وحقيقة التقوى جعل النفس في وقاية من كل ما يبعد عن الله تعالى ولهذا قال بعض المحققين التقوى أن يتجنب الإنسان بغاية جهده الأخلاق الحيوانية، ويتخصص بالأخلاق الملكية، فلا يكون متكبرا كالنمر، ولا معينا كالكلب، ولا حقودا كالجمل، ولا غمرا كالثور، ولا جاهلا كالحمار - وقد نبه بالآية أن العبادة لله تعالى هي المبلغة بنا إلى نهاية التقوى التي يستحق بها حوار الله تعالى، نحو قوله عز وجل: ﴿وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩﴾⟪22:77⟫ وقوله: ﴿وَأَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ﴾⟪3:132⟫."}, {"a": [22], "v": 1, "p": 111, "ev": 1, "ep": 115, "sid": 112, "t": "قوله - عز وجل -: ﴿ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشٗا وَٱلسَّمَآءَ بِنَآءٗ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ﴾⟪2:22⟫ الآية (22) - سورة البقرة.\nجعل: لفظ عام في الافعال كلها، ويتصرف على ثلاثة أوجه: تارة تجري مجرى صار، و \" طفق \"\n⟦1:112⟧\nفلا يتعدى مثل قولك جعل زيد يقول كذا، قال الشاعر:\nوقد جعلت قلوص بني سهيل\n....\nمن الأكوار مرتعها قريب\nوتارة تجري مجرى \" أوجد، فيتعدى إلى مفعول واحد، نحو قوله تعالى: ﴿وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَۖ﴾⟪6:1⟫ وتارة تجري نجرى صير وكون فيتعدى إلى مفعولين نحو قوله تعالى ﴿جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَٰشٗا﴾⟪2:22⟫ وتقول جعلته خارجا إذا جملته على الخروج وإذا أخبرت عنه بالخروج أو حكمت له سواء كان خارجا أو لم يكن والفراش والبساط متقاربان وهو كل ما فرش من ثوب أو غيره والبناء لكل مرتفع وحائط وغيره والقصد بالآية إلى ما جعله الله تعالى لنا من الآية الواصلة إلينا من السماء والأرض وما بينهما ودل على ذلك بأظهر الآلاء وأقربها من الحواس وقد بسط ذلك المعنى بأبلغ من هذا في قوله ﴿خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ﴾⟪3:190⟫ وهذا المعنى على مقتضى ظاهر اللفظ.\nوقد قال بعض المفسرين إن الله تعالى مع إرادته لهذا المعنى جعل ذلك مثلا فذلك أنه جعل الأرض فراشا أي مركبا من قوله: \" افترشت البعير \" إذا ركبته، (والسماء بناء) أي الجنة مقرا أو منزلا، وجعل ما يصل إلينا من الوحي والعلم ماء، وما يثمره من الأعمال الصالحة التي هي سبب الحياة الأبدية ثمرات، وهذا إذا جعل مثلا فليس ببعيد، إذ قد علم أن السماء تجعل مثلا لكل منزلة رفيعة كقول الشاعر:\nنالوا السماء فأمسكوا بعنانها ...\nحتى إذا كانوا هناك استمسكوا\nولا منزلة أرفع من الجنة، ثم لما كانت الجنة في السماء على ما روي في الخبر صح أن يعبر به عنها وقد جعل الأرض مركبا لنا لما روى في الخبر: \" اجعلوا الدنيا مطية تبلغكم إلى الآخرة، واجعلوا الآخرة دار مقركم ومحط رحالكم، وجعل المساء مثلا للعلم والحكمة حتى قيل في قوله تعالى ﴿وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَسۡمَعُونَ﴾⟪16:65⟫ أنه عنى بالماء القرآن بدلالة أنه علقه بالسماع، وليس الماء مما يسمع، وفي قوله - عز وجل - ﴿أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَالَتۡ أَوۡدِيَةُۢ بِقَدَرِهَا﴾⟪13:17⟫ أنه عنى به القرآن، فذلك روي عن ابن عباس - رضي الله عنهما -، ويروى أن رجلا قال لابن سيرين:\n⟦1:113⟧\nرأيت في منامي كأن ماء يتبعني وأنا أهرب منه وكنت عطشان \"، فقال إنه يعرض عليك علم أنت محتاج إلهي وتأبى أن تتعلمه \"، وجعل الثمر مثلا لما يتحصل من الأفعال الصالحة عن ذلك البيان، وقد جعل الله تعالى الماء والثمر مثلا في قوله ﴿ضَرَبَ ٱللَّهُ مَثَلٗا كَلِمَةٗ طَيِّبَةٗ كَشَجَرَةٖ طَيِّبَةٍ أَصۡلُهَا ثَابِتٞ وَفَرۡعُهَا فِي ٱلسَّمَآءِ﴾⟪14:24⟫ الآية ..\n، وجعل بعضهم ذلك مثلا على وجه آخر، فقال: الأرض مثل للأبدان، والسماء مثل للعقل، والماء مثل لما أفاض الله به علينا من العلوم المكتسبة التي تحصل بواسطة العقل.\nوالثمرات التي جعلها الله رزقا لنا مثل لما يحصل من الأفعال التي تقتضيها العلوم والله أعلم.\nوهذا يكون أبلغ في المعنى، لأنه يحصل مع المعنى المحسوس معنى معقول.\nوالله أعلم.\nقوله - عز وجل -: ﴿فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادٗا وَأَنتُمۡ تَعۡلَمُونَ﴾⟪2:22⟫ الآية: (22) - سورة البقرة.\nالند والشبه والمساوي والشكل والمثل متقاربة المعنى، لكن بيناه فروق - فند الشيء هو المشارك له في الجوهر وإن خالفه في الكمية والكيفية وشبهه مماثله في الكيفية، وإن خالفه في غيرها ومساويه مماثله في الكمية كلها وإن خالفه في غيرها، وشكله مماثله في القدر والمساحة ويدل على هذا الفرقان إنه إذا قيل ما هذا؟ فيقال: ند كذا، أو يقال كم هذا؟ فيقال مساو لكذا، أو يقال: كيف هذا؟ فيقال: شبه كذا قنع المخاطب متى عرف المشبه به، ولو قال كم هذا ؟ فيقال: شبه هذا أو قال كيف هذا؟ فيقال مساو لهذا لم يقنع به، والمثل عام في جميع ذلك، ولهذا لما أراد الله تعالى نفي الشبيه من كل وجه خصه بالذكر، فقال: ﴿لَيۡسَ كَمِثۡلِهِۦ شَيۡءٞۖ﴾⟪42:11⟫ وقال أبو عبيد: الند \" هو الضد، وهذا نظر منه إلى بعض الأنداد،\n⟦1:114⟧\nوذلك أن الشيئين قد يشتركان في الجوهر، ثم يختلفان في فصل ما، كالإنسان والفرس فإنهما مشتركان في الحيوانية، ومنفصلان في كثير من المعاني فمن اعتبر في مثل ذلك ما بينهما من الفصل قال: الند: هو الضد أو المخالف لأن أهل اللغة يطلقون الضد على المتقابلين، وعلى المختلفين كثيرا على ما يدل عليه كلامهم في الأضداد، وقوله: ﴿فَلَا تَجۡعَلُواْ لِلَّهِ أَندَادٗا﴾⟪2:22⟫ عام في النهي عن الشرك المطلق وعن الدقائق المؤدية إلى الشرك المنبأ عنه بقوله: ﴿وَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ﴾⟪12:106⟫ ولهذا قال ابن عباس - رضي الله تعالى عنهما - في هذه الآية هو قول الرجل: (لولا نباح الكلب لدخل علي اللص) وقيل: هو نهي لقوم كانوا يقولون: إن شاء الله وشاء رسول الله - عليه السلام: \" أمثلان أمثلان؟ قولوا إن شاء الله \" فأنزل الله هذه الآية.\nإن قيل: ما وجه قوله: \" وأنتم تعلمون \"؟ فإن ذلك إن جعلته خبرا مستأنفا، فلابد له من ذكر معلم يقترن به حتى يحصل به تمام الخبر، إن جعلته حالا يصير تقديره: \" لا تجعلوا له أندادا في حال علمكم \"، وذلك غير صحيح، لأن جعل الأنداد محظور في كل حال، قيل إن ذلك حال للمنتهي، وليس الاتيان به شرطا لقصر الحكم على هذه الحال، وإنما هو تنبيه على قبح فعلهم، لأن مرتكب القبيح مع علمه بقبحه أعظم جرما، وإذا قيل: \" لا تكفر معاندا \" فذلك نهي عن الكفر وعن العناد، فكذلك هذا، وعلى هذا قوله تعالى: ﴿وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ﴾⟪23:117⟫ ثم قوله: ﴿وَأَنتُمۡ تَعۡلَمُونَ﴾⟪2:22⟫ عام فيمن حصل له العلم بذلك، وفيمن له التمكن مع العلم به، فقد\n⟦1:115⟧\nيصف من حصل له التمكن من الشيء الترشح له بذلك الشيء كتميتهم العصير خمرا، الصبي ناطقا، والنائم عالما قد تقرر في عقل كل عاقل إذا تأمل أدنى نظر أنه لابد للموجودات من موجد لها يخالفها، يصح أن يقال لهم: \" أنتم تعلمن \" وبهذا الوجه قال تعالى: ﴿قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أَمَّن يَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَمَن يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَمَن يُدَبِّرُ ٱلۡأَمۡرَۚ فَسَيَقُولُونَ ٱللَّهُۚ﴾⟪10:31⟫ ومعلوم أنهم لا يقولون ذلك إلا بأدنى تأمل واعتبار."}, {"a": [23], "v": 1, "p": 115, "ev": 1, "ep": 119, "sid": 116, "t": "قوله - عز وجل - ﴿وَإِن كُنتُمۡ فِي رَيۡبٖ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ بِسُورَةٖ مِّن مِّثۡلِهِۦ﴾⟪2:23⟫ الآية (23) - سورة البقرة.\nقد تقدم الكلام في الريب، وأما الفرق بين الشك والمرية، والريب والأرابة، والتخمين والحدس، والوهم والخيال، والحسبان والظن، فإنه يذكرها هنا إذا كانت معرفته نافعة، فنقول: وبالله التوفيق: إن الشك هو وقوف النفس بين الشيئين المتقابلين بحيث لا يترجع أحدهما على الآخر بأمارة، والمرية هي التردد في المتقابلين، وطلب الإمارة مأخوذ من بري الضرع، أي منحه للدر، فكأنه يحصل مع الشك تردد في طلب ما يقتضي عليه الظن.\nوالريب أن تتوهم في الشيء أمرا ما، ثم ينكشف عما توهمت فيه، والأرابة أن تتوهمه، فينكشف بخلاف ما توهمت، ولهذا قيل: \" القرآن فيه أرابة وليس فيه ريب \"، والتخمين توهم لا عن إمارة.\nوالحدس إسراع الحكم بما لا يأتي به الهاجس من غير توقف فيه مأخوذ من حدس في سيره، أي أسرع والوهم صورة تتصورها في نفسك سواء كان لها وجود من خارج كصورة إنسان ما، أم لم يكن له وجود كعنقاء مغرب، وغزائل، والخيال تصور ما أدركه الحاسة في النفس.\nوالحسبان: اعتقاد عن أمارة اعتددت به، سواء كان له وجود في الحقيقة، أو ولم يكن وهو مشتق من حسبت الحساب، والظن: أعم معنى من ذلك كله فإنه اعتقاد عن أمارة ما مما قد ثبت، فمتى كانت تلك الأمارة ضعيفة جرى مجرى \" خلت\n⟦1:116⟧\nوحسبت \"، ومتى كانت الامارة قوية جرى مجرى \" علمت \" وكتردده بين هذين.\nقال أهل اللغة: \" ظننت \" قد يكون بمعنى: \" خلت \" وبمعنى: \" تيقنت \"، ومتى كانت الأمارة قوية، ولحق بباب العلم استعمل معه \" أن \" الثقيلة والخفيفة منه نحو: ﴿ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ﴾⟪2:46⟫ وقوله: ﴿عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ﴾⟪73:20⟫ ومتى كانت ضعيفة، استعمل معه \" أن \" المختصة بالمعدومين من الفعل، نحو قوله: ﴿تَظُنُّ أَن يُفۡعَلَ بِهَا فَاقِرَةٞ﴾⟪75:25⟫ وقد تقدم الكلام في الإنزال والتنزيل وفي معنى العبد.\nوأما تخصيص إضافة العبد إلى الله في كثير من المواضع، فتنبيه على مدحه في كونه مطيعا له متصرفا عن أمره، وأنه غير متعرج على غيره، ولا مؤتمر لسواه كمن سماهم \" عبدة الطاغوت \"، و \" عبد الدرهم والدينار \" وتنبيه أنهم ممن وصفهم الله بقوله: ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾⟪9:111⟫ وتنبيه أنه يجري مجرى الملك الموصوف في قوله ﴿لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ﴾⟪66:6⟫ ثم إضافته بنون الملكية مبالغة في الاختصاص، وكل إضافة إليه تعالى على هذه الوجه، فالمبالغة والسورة المنزلة في نحو:\nألم تر أن الله أعطاك سورة\nويقال للمحيط بالمدينة \" سور \" لحياطته بجملتها، وتسمية القطعة من القرآن بذلك لكونه كالمحاط بها إحاطة السور بالمدينة، أو لكونها منزلة ما من القرآن كما تقدم، ومن قال سؤرة بالهمز، فمن: أسارت أي: أبقيت قطعة، فكان ذلك قطعة مفرزة من جملته، وقوله:\n⟦1:117⟧\n\" من مثله \"، قيل: من مثل القرآن، وقيل: من مثل النبي [عليه السلام] من البشر - تنبيها أن مثله ليس في طرق البشر، ومن على الوجه الأول: للتبغيض، وعلى الثاني: للابتداء.\nقوله - عز وجل -: ﴿وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ﴾⟪2:23⟫.\nالآية: (23) - سورة البقرة.\nالشهادة: تبين الشيء الحاضر، فقولهم: \" شهد زيد \" في المعنى من قولهم: \" حضر \" وإن كان قد يفسر به، ولما كان تبين الشيء على ضربين: تبين بالبصر، وتنبين بالبصيرة، والحضور على ضربين: حضور بالذات، وحضور بالتصور، صارت الشهادة تستعمل على أوجه بحسب ذلك، فيقال ذلك لحصول قربة ومنزلة، ومنه قليل: استشهد فلان \"، \" وهو شهيد \"، كأنه حضر وتبين ما كان يرجوه، واستعمال ذلك فيه كاستعمال القريب نحو قوله: ﴿ٱلۡمَلَٰٓئِكَةُ ٱلۡمُقَرَّبُونَۚ﴾⟪4:172⟫ ولهذه العنى قال: ﴿إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ﴾⟪7:206⟫، وقال في الشهداء: ﴿بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ﴾⟪3:169⟫، وقالوا: \" أنا شاهد لهذا الأمر \"، أي عارف به متصور له - إشارة إلي قولهم \" لئن غبت عن عيني لما غبت عن قلبي \".\nوقالوا: \" شاهده \" أي: ناصره، وعلى نحوه قال [تعالى]: ﴿إِنَّ ٱللَّهَ مَعَنَاۖ﴾⟪9:40⟫ وقالوا: \" صحبك الله، وأما الشهادة المتعارفة: فأصلها الحضور بالقلب والتبين، ثم يقال ذلك إذا عبر عنه باللسان، ولذلك متى أطلق لفظ الشهادة على ما يظهر من اللسان دون حصوله في القلب عد كذبا، كقوله تعالى في المنافقين حيث قالوا: ﴿نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ﴾⟪63:1⟫، فكذبهم وقال: ﴿وَٱللَّهُ يَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ﴾⟪63:1⟫ ثم يقال لكل ما يدل على شيء شهادة وإن لم يكن قولا فقوله: ﴿وَٱدۡعُواْ شُهَدَآءَكُم﴾⟪2:23⟫ قد فسر على ما يقتضيه لفظ\n⟦1:118⟧\nالشهادة، قال ابن عباس - رضي الله عنهما - معناه: أعوانكم، وقال مجاهد: معناه الذين يشهدون لكم، وقال غيرهما: أئمتكم نحو: ﴿وَنَزَعۡنَا مِن كُلِّ أُمَّةٖ﴾⟪28:75⟫، وكأنما عنى بذلك الكبير الذي لا يبرم أمرا من دونهم كقولهم: \" فلان يحضر به النوادي وهو من أهل النجوى \" وبضده هجى من قبيل فيه بيت:\nمخلفون، ويقضي الناس أمرهم ...\nوهم بغيب وفي عمياء ما شعروا\nوأما الصدق: فإنه يحد بأنه مطابقة الخبر المخبر عنه، لكن حقيقته وتمامه أن يتطابق في ذلك أشياء، وجود المخبر عنه على ما أخبر عنه، واعتقاد المخبر فيه ذلك عن والاعتقاد وبخلافه، صح أن يوصف بالكذب ...\nألا ترى أن الله تعالى كذب المنافقين في إخبارهم \" إنك لرسول الله \" لما كان اعتقادهم غير مطابق لقولهم؟ وإذا قال لك من أعتقد كون زيد في الدار، ولم يكن فيها صح أن يقال كذب، وإن كان قوله مطابقا لاعتقاده، ولما كان اللسان ترجمان القلب، صح أن يقال: \" صح في اعتقاده أو كذب \"، وقد يتجوز أيضا بذلك في جميع الأفعال، فيقال لكل فعل جميل على ما يجب صدق، ولما كان بخلافه [قيل] كذب، ويقال أيضا لكل شيء يعتقد فيه اعتقادا ما فوجد مطابقا لذلك صدق، وإن وجد بخلافه كذب، ووجه الآية أن الله تعالى تحداهم بأن قال: \" ادعوا أعوانكم وأنصاركم \" وأستعينوا بكل ناصر لكم غير الله الذي هو مفزع الكل، وانظروا هل فب طوقكم الإتيان بمثله - تنبيها على أن ذلك لو أتى به محمد من قبله لقدرتم أنتم مع تظاهركم على الإتيان بمثله، ويحوز أن يكون قوله: ﴿مِّن دُونِ ٱللَّهِ﴾⟪2:23⟫ ذما لهم أي: ادعوا أعوانكم التي من عادتكم الاستعانة بهم الذين هو غير\n⟦1:119⟧\nالله، ويجوز أن يكون معناه (وادعوا شهداءكم الذين لكم من دون الله)، فإن الاستعانة به ليس بكم، وعلقه بقوله: ﴿إِن كُنتُمۡ صَٰدِقِينَ﴾⟪2:23⟫ - تنبيها أن إقامة الدلالة على الشيء الصدق ليس يقصر، فعجزكم عنه دلالة على أنكم كاذبون في دعواكم."}, {"a": [24], "v": 1, "p": 119, "ev": 1, "ep": 121, "sid": 120, "t": "قوله - عز وجل -: ﴿فَإِن لَّمۡ تَفۡعَلُواْ وَلَن تَفۡعَلُواْ فَٱتَّقُواْ ٱلنَّارَ ٱلَّتِي وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَٰفِرِينَ﴾⟪2:24⟫.\nالآية: (24) - سورة البقرة.\nلفظ الفعل أعم من معنى سائر أخواته، نحو: العمل، والصنع، والإبداع، والإحداث، والخلق والكسب وذاك أن الإبداع أكثر ما يقال في إيجاد عين عن عدم، وليس حقيقة ذلك إلا الله تعالى، والأحداث يقال في إيجاد الأعيان والأعراض معا، والعمل لا يقال إلا ما كان عن فكر وروية، ولهذا قرن بالعلم، فقيل: علم وعمل، حتى قال بعض الأدباء: \" قلب لفظ \" العمل عن لفظ \" العلم \" تنبيها أنه من مقتضاه، والصنع يقال لإيجاد الصورة في المواد كالصياغة والبناء فإن الصائغ يوجد صورة الخاتم والخلخال في الذهب والفضة، والبناء يوجد صورة البناء في الطين، والكسب أكثر ما يقال في اجتلاب المنافع، وقد يقال أيضا في اجتلاب المضار مقيدا، والخلق قد تقدم القول فيه، وقد أمر الله بالتقوى على ثلاثة أوجه، وخص بكل وجه عصابة من الناس وذلك بحسب اختلاف مراتبهم من العلم ومكانهم من الإيمان، فالأول: حث الإنسان على اتقاء عقوبة الله برؤية ذنوبه، وذلك في قوله: ﴿وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ﴾⟪3:131⟫، ﴿وَٱتَّقُواْ يَوۡمٗا تُرۡجَعُونَ فِيهِ إِلَى ٱللَّهِۖ﴾⟪2:281⟫ والثاني: حث على\n⟦1:120⟧\nاتقائه بروية آلائه ونعمه لقوله: ﴿يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ﴾ والثالث: حث على تقواه برؤية وحدانيته دون الوسائط وذلك في قوله: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ﴾.\nوجعلها على ثلاثة مراتب حسب ما سنه تعالى في سياسة الأصناف الثلاثة من الناس الخاصة والعامة، وبهذا الاعتبار قسمهم تعالى ثلاثة أقسام في قوله تعالى: ﴿فَمِنۡهُمۡ ظَالِمٞ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ﴾⟪35:32⟫ وأشرف هذه المنازل \" تقوى الله \" تعالى من غير رؤية الوسايط بلا مخالفة ولا رجاء، ولذلك عظم ثوابه بقوله: ﴿وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا ۝ وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ﴾⟪65:2-3⟫ وهم الاتقون المعنيون بقوله تعالى: ﴿إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ﴾⟪49:13⟫ والمعبر عنهم بقوله: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ﴾⟪98:7⟫ والوقود: الحطب الذي يوقد به، ولذلك فسر بأنه دقاق الحطب، لأنه الدقاق الذي يوقد به، ولما كانت نار الدنيا محتاجة إلى دقاق توقد به، ونار جهنم مستغنية عن ذلك، بل يكتفي في إيقادها بالناس وبالحجارة التي ليست من عادة النيران المشاهدة أن يتقدبها عظم أمرها ومن قال: أراد بذلك حجارة \" الكبريت \" فإنما عنى أن الحجارة لتلك النار كحجارة الكبريت لنار الدنيا، وقوله: أعدت أصله في العدد وهو الإحصاء، لكن العد يتجوز به على أوجه فيقال: شيء معدود ومحصور للقليل مقابلة بما لا يحصى كثرة، ويقال على الضد من ذلك، وجيش عديد، وإنهم لذو عدد، أي: كثيرة، وذلك مقابلة بما لا يحتاج إلى حصره وتعداده لقلته، ولهذا قيل: أعددت هذا لكذا، أي جعلته معادا للمعد له، يتناول منه بحسب حاجته إليه وقد ألزمهم الله تعالى بهذه الآية الحجة بأنكم إن أتيتم بمثله، فقد أدخصتم حجته،\n⟦1:121⟧\nوإن لم تأتوا به لزمتكم الحجة، ووجب عليكم أن تتقوا عقابه.\nوفصل بين الشرط والجزاء بحكم جزم أن لا تأتوا بمثله، وذلك زيادة في إعجازه لوجود مخبره على ما أخبر به وذلك مثل قوله: ﴿قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ﴾⟪17:88⟫ الآية، فإن قيل كيف خص الكافرين بالنار دون الفاسقين؟ قيل: يجوز أن يكون أراد أن هذا الضرب من النار يختص به الكفار، وهي المخصوصة أيضا بقوله: ﴿أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ﴾⟪40:46⟫ وقوله: ﴿إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ﴾⟪4:145⟫ ثم إذا قيل: \" أعد هذا لزيد \" لا يقتضي أن لا يكون معدا لغيره، بل قد يكتفي بأعظم الشيئين عن الآخر نحو قوله: ﴿سَرَٰبِيلَ تَقِيكُمُ ٱلۡحَرَّ﴾⟪16:81⟫ لم يذكر معه البرد، فيكون النار على هذا الوجه للجنس، وعلى الأول للنوع .."}, {"a": [25], "v": 1, "p": 122, "ev": 1, "ep": 127, "sid": 123, "t": "قوله - عز وجل - ﴿وَبَشِّرِ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ كُلَّمَا رُزِقُواْ مِنۡهَا مِن ثَمَرَةٖ رِّزۡقٗا قَالُواْ هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ وَأُتُواْ بِهِۦ مُتَشَٰبِهٗاۖ﴾⟪2:25⟫\nالآية: (25) - سورة البقرة.\nأصل بشرته تلقيته مني ببشرة ووجه طلق، وذاك أن من شأن من أتى بخبر سار أن يكون طلق الوجه، ومن أتى بخبر بخلافه يكون عابس الوجه وقيل معنى بشرته: أطلقت بشرته بما أخبرته فإن من ناله سرور، طار دمه منتشرا في صفحة وجهه، ومن ناله سوء يقيض دمه فاصفر أو اسود وقيل: بشرتهك أظهرت له خبرا دلت بشرته على المسرة به، أي ظاهره فاستعير لظاهر الخبر البشرة وذلك لكثرة ما يدل وجه الشيء على باطنه\nفإن قيل: فإن كانت البشارة للأخبار السارة، فما وجه قوله تعالى:\n﴿فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ﴾؟ قيل إن مثل ذلك قد يستعمل على سبيل التهكم نحو:\n\" تحية بينهم ضرب وجيع \"\nتنبيها أن السار لهم الإخبار بالعذاب الآليم، فما الظن بما وراءه؟ والإيمان لما كان في الأصل للتحقيق والتصديق، قيل: ما ذكره الله تعالى إلا قرن به الأعمال الصالحة، تنبيها أن الاعتقاد لا يغني من دون العمل، فالعلم أس والعمل بناء، ولا غناء للأس ما لم يكن بناء كما لا بناء ما لم يكن له أس ولذلك قيل: \" لولا العمل لم يطلب علم \"، ولولا العلم لم يكن عمل، فإذا حقهما أن يتلازما والجن: أصله المستر عن حس البصر وسمى الجن لاستتاره عنه، ثم اشتق من الجن، فقيل جن فلان، وبنى على فعل نبأ \" عامة الأدواء نحو:\n⟦1:123⟧\n\" زكم \" و \" حم \" ولقي والجنان: القلب، لكونه مستورا عن البصر، و \" جن الليل \" والمجن لذلك وقيل للبستان ذي الأشجار جنة، لاستتاره بها، والجنة قيل: [تسمى تشبيها] بجنة الأرض وإن كان بينهما بون، وقيل: سميت بذلك، لأنه ستر في الدنيا حقيقة ما أعد الناس فيها من عظم الآلاء وبذلك أخبر تعالى في قوله: ﴿فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ﴾⟪32:17⟫ وإنما قال: \" جنات \" بلفظ الجمع لما قال ابن عباس - - رضي الله تعالى عنهما - \" إن الجنان سبع: جنة الفردوس، وجنة عدن، وجنة النعيم، وجنة المأوى، ودار الخلد، ودار السلام، وعليون \" والجري: المر السريع، ويقال ذلك في الماء والرياح والسحاب والفرس، ويقال للرسول والوكيل المتحققين في الحال جري، والاتيان: عام في المجيء والذهاب وفيما كان طبعا وقهريا، والآتي: يقال للماء الجاري، ولما وقع فيه من خشب ونحوه ولمجرى الماء القريب أيضا\nإن قيل: لم قال: ﴿تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ﴾⟪2:25⟫ وقد علم أن الماء في البساتين إذا كان جاريا على وجع الأرض أحسن منها إذا كان جاريا تحتها؟ قيل: عنى أنهارا جارية تحت الأشجار، لا تحت الأرض، وقد روي عن مسروق ما يدل على ذلك، وهو أن كل أنهار الجنة تجري في غير أخاديد،\nإن قيل: كيف قالوا:\n﴿هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ﴾⟪2:25⟫ وما كان من قبل قد فنى وعدم؟ قيل: لفظة \" هذا \" وأخواته يشار بها إلى العين الموجودة طورا، وإلى النوع والجنس طورا.\nوالنوع من حيث ما هو نوع ليس يفنى، وإنما الذي يفنى هو الجزئيات وعلى ذلك تقول في الإشارة إلى نهر جار: \" هذا الماء\n⟦1:124⟧\nلا يفنى \" وأنت لا تعني بذلك الجزئيات المشاعدة منه، وإنما تعني به النوع المعلوم وقوله: ﴿مِن قَبۡلُۖ﴾⟪2:25⟫ هو للمتقدم، فقيل: عنى بذلك ما أتوا به قبل ذلك في الجنة، وإليه ذهب الحسن ويحيى بن أبي كثير، فقال: \" إذا أوتي أحدهم بصحفة فيأكل منها ثم يؤتى بآخر، فيقول: هذا الذي رزقنا من قبل، فيقول له الملك: كل فاللون واحد والطعم مختلف \"، وقال ابن عباس - رضي الله تعالى عنهما - ﴿رُزِقۡنَا مِن قَبۡلُۖ﴾⟪2:25⟫ أي في الدنيا شبهه.\nوابن جرير رجح هذا الوجه، وقال: إن قوله: (كلما) عام يقتضي أنهم قالوا ذلك في كل مرة من غير تخصيص، ومتى جعل ذلك الأولى، اقتضى أن يكون مخصوصا خلاف ما يقتضيه عموم الآية، وقال بعض المفسرين قول ابن عباس\n-[رضي الله عنهما]-\nفي قوله: ﴿هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ﴾⟪2:25⟫ أي: في الدنيا، يعني ثواب ما رزقنا من المعارف كقوله: ﴿ذُوقُواْ مَا كُنتُمۡ تَعۡمَلُونَ﴾⟪29:55⟫، قال: ويدل على صحة هذا أن ابن عباس - رضي الله تعالى عنهما - قال: \" ليس في الجنة من أطعمة الدنيا إلا الأسماء \"، والمتشابه: المتماثل في الكيفية، ولهذا يقال فيكا لا يتميز أحدهما عن الآخر متشابه، وكذلك للواقع من الكلام بين معنيين فصاعدا ومتشابه والشبهة في الشيء ما يقع فيه من مشابهة الغير، فقوله: ﴿وَأُتُواْ بِهِۦ مُتَشَٰبِهٗاۖ﴾⟪2:25⟫، قيل: هو تفسير لقوله: ﴿هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ﴾⟪2:25⟫ أي يشبهه اسما ولونا لا طعما وحقيقة وقيل: عنى به متماثلا في الكمال وأن لا تقارب، فيه كأطعمة الدنيا، وقال بعض المفسرين: إن الآية مثل لا على الحقيقة، وقد نبه على كونه مثلا بقوله بعده: ﴿إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلٗا مَّا بَعُوضَةٗ فَمَا فَوۡقَهَاۚ﴾⟪2:26⟫ والأنهار مثل لمجاري الخيرات، كقولك: ينابيع الحكم، وأنهار الفعل والرزق لم يعن به ما يؤكل فقط، وإنما هو كقولك: \" رزقت فهما وعلما \" والثمرة: اسم\n⟦1:125⟧\nلما يتحصل عن الشيء، كقولهم: \" ثمرة العلم العمل الصالح، وثمرة العمل الصالح الجنة \" ومعناه: كلما اعطوا في الجنة جزاء لما رزقوا من المعارف والأعمال، ﴿قَالُواْ هَٰذَا ٱلَّذِي رُزِقۡنَا مِن قَبۡلُۖ﴾⟪2:25⟫ أي: هذا ثواب الذي وفقنا له في الدنيا.\nوهذا القول وإن كان لمجازه مساغ في اللغة، فهو ترك لما روي عن السلف في تفسير الآية، وقد طعن في هذه الآية وأمثالها من الآيات قوم من المتفلسفين والطبيعيين، وقالوا: \" إن الجنة لا يصح فيها الأكل والشرب، فإن الأكل لا يطيب إلا عن جوع، والجوع مرض وأذى، والأكل مداواة له، ولا مرض ولا أذى بوجه في الجنة، ثم إن الطعام يصير بعضه ثقلا بعد طبخ المعدة إياه فيخرج من البدن، وبعضه يصير غذاء يزيد في البدن بقدر ما يتحلل منه، وإلا خرج به البدن عن الاعتدال.\nوكل ذلك لا يصح إلا في دار الكون.\nوالفساد دون دار الخلد والبقاء \".\nوهذا كلام من نظر إلى الأجساد في الآخرة نظره إليها في هذه الدنيا، وهي مركبة تركيبا معرضا للاستحالات، ولم يعلم أن الله تعالى [قادر على أن] يعيدها إعادة لا تعتورها الاستحالات، ويجعل لها أطعمة يتلذذ بها، فلا يكون لها ثقل ولا تغير منكر، وقد دل على ذلك تعريضا وتصريحا، أما إعادتها على وجه معرى من الاستحالات، فقوله تعالى: ﴿وَنُنشِئَكُمۡ فِي مَا لَا تَعۡلَمُونَ﴾⟪56:61⟫، وبقوله عليه السلام في أهل الجنة: (جرد مرد مكحول)، وأم إن أطعمتها لا يستحيل فبقوله عليه السلام: (إن أهل الجنة لا يبولون ولا يتغوطون إنما هو عرق يجري من أعراضهم مثل المسك).\n⟦1:126⟧\nويقول ابن عباس \" رضي الله عنهما \" \" ليس في الجنة شيء ما في الدنيا إلا أسماوها \"، فإن الله تعالى سمي الماء واللبن والخمر والعسل والسندس والحرير والمسك والزنجبيل، ووصف لكم ما في أيديكم ليحلو عندكم، ولكي تهتدي، إليه قلوبكم، زليس لهذا القول منه وجه إلا التوقيف، إذ لا مدخل للاجتهاد فيه، وروي أن يهوديا سأل النبي - صلى الله عليه وسلم - \" أتزعم أن في الجنة نكاحا وأكلا وشربا، ومن أكل وشرب كانت له عذرة؟ فقال النبي - عليه السلام -: \" والذي نفسي بيده إن فيها أكلا، وشربا، ونكاحا، ويخرج منهم عرق أطيب من ريح المسك \"، فقال رجل: صدق رسول الله، خلق الله دودا يأكل مما تأكلون، ويشرب مما تشربون، فيخلف غسلا سائغا \" فقال عليه السلام: \" هذا مثل طعام الجنة أهل الجنة \" وفي هذا إشارة عجيبة، فإنه إذا أمكن أن يأكل دود أطعمة مستحلية، فتخلف جنسا طيبا يبقى أطول مدة، فلا يلحقه فساد، فكيف ينكر أن يتناول أهل الجنة طعاما معرى من العفونات والاستحالات، فيخلف منه مسك؟ والذي يستبعده بعض الناس من ذلك هو أنهم يريدون أم يتصوروا أبدانا متناولة لأطعمة لا استحالة فيها ولا تغير لها، ولا يكون منها فضولات، وتصور ذلك محال، وذاك أن التصور: هو إدراك الوهم خيال ما أدركه من الحس وما لا يدرك الحس جزءه ولا كله، كيف يمكنه، تصوره؟ ولو كان للإنسان سبيل إلى تصور لك، لما قال تعالى: ﴿فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ﴾⟪32:17⟫، ولما قال \" عليه السلام \" مخبرا عن الله تعالى: (أعدت لعبادي الصالحين ما لا عين رأت، ولا أذن سمعت ولا خطر على قلب بشر)، وجملة الأمر: يجب أن يكون معلوما أن النقصانات منفية عن الجنة، لأنها من الأعدام، وليس في الجنة أعدام، إذ الجنة في غاية الكمال والتمام ..\n⟦1:127⟧\nقوله - عز وجل -: ﴿وَلَهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَهُمۡ فِيهَا خَٰلِدُونَ﴾⟪2:25⟫ الآية: (25) سورة البقرة.\nالزوج: يقال لكل واحد من القرينين من الذكر والأنثى في الحيوان المتزواجة، ومن القرينين في غيرهما، كزوج الخف والنعل، ولكل ما معه آخر مقارن له - مماثلا كان أو مضادا، مركبا معه أو مفردا، فقوله تعالى: ﴿ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ﴾⟪37:22⟫ أي.\nأشكالهم وموافقيهم في الدين، ولم يرج الرجل وحليلته، فقد تكون تحت المؤمن الكافرة وتحت الكافر المؤمنة، وقوله تعالى: ﴿وَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ﴾⟪51:49⟫ أي اثنين، إما من حيث الأعداد، أو من حيث التركيب - تنبيها أنه تعالى هو الفرد من كل وجه، وما سواه زوج من وجه ما، والزوجية: أي أنثوية يقتضي كونها محدثة، والتطهير يقال في الأجسام والأخلاق والأفعال جميعا، وقيل في قوله: ﴿وَثِيَابَكَ فَطَهِّرۡ﴾⟪74:4⟫.\nأي نفسك نقها من الأوساخ، وذلك مخاطبة لككافة وإن كان لفظه للنبي - عليه السلام - وقال تعالى: ﴿إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرٗا﴾⟪33:33⟫، ومعلوم أنه تعالى لم يرد تطهيرا عن نجاسة في ثوب وبدن، وإنما أراد تطهير النفس الذي يستحق به المدح والخلود والبقاء الدائم وأصله لما يطول مكثه، ومنه قيل للأثافي والأحجار \" خوالد \"، والخلد: اسم للجزء يبقى من الإنسان على حالته مادام حيا ..."}, {"a": [26], "v": 1, "p": 128, "ev": 1, "ep": 131, "sid": 129, "t": "قوله - عز وجل -: ﴿إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلٗا مَّا بَعُوضَةٗ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۘ يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ﴾⟪2:26⟫.\nالآية (26) سورة البقرة.\nالحياء: عارض للفرع من النقيصة، وذلك بين الوقاحة والخجل، فإن الوقاحة هي الجرأة على الإعال القبيحة من غير مبالاة، والخجل انحصار النفس عن الفعل، والحياء مأخوذة من لفظ (الحياة) التر يراد بها العلم والعقل، ووجه ذلك أن الحياء أس العقل، إذ هو أول أمارة منه تظهر من الصبي، ولهذا قال عليه السلام: \" من لا حياء له لا إيمان له \"، لأن الحياء أول منزلة من العقل، والإيمان آخر منزلة له، ومحال أن يحصل آخر المنزلة لمن لم يحصل له الأولى، وأما الحياء الذي هو الفرح، فسمي بذلك لكونه مستحبا من ظهورة، ومن أجل ذلك قيل: \" شورت لفلان \" أي خجلته خجل من يظهر شواره أي فرحة والضرب أصله وقع شيء على شيء ثم تجوز به على أنظار مختلفة، ولما قيل: \" ضربت الدرهم \"، و \" درهم ضرب \" أي مصوغ، استعير منه: \" ضربت المثل \" والكلام في المثل، والمثل قد تقدم، وما في قوله: \" مثلا ما \" للمبالغة في التنكير، فإن \" ما \" في الخبر إما أن تكون معرفة، فتكون موصلة، أو نكرة، وذلك على ثلاثة أوجة: إما موصوفة نحو قوله:\nرب ما تجزع النفوس من الأم\n....\nر فرجة كحل العقال\nأو مبتدأ بلا صفة وذلك في قولهم: \" ما أحسن زيدا \" على مذهب \" سيبويه \"، وإما تابعا\n⟦1:129⟧\nلاسم منكور - تنبيها أنه لم يقصد به معين، نحو: \" رأيت رجلا ما \"، وقوله: \" فما فوقها \"، قيل معناه: ما دونها، وإنما عنى ما فوقها في الصغر، ففسره بدون، فظن بعض أهل اللغة أن فوق يكون بمعنى \" دون \" فأخرجه في جملة ما صنف من الأضداد والحق: لفظ عام لصدق المقال وصواب الفعال، يقال: قول حق، كقولك صواب، وقيل: الحق هو الذي لا يزاحمه في ذاته ضد، ولهذا وصف الله تعالى به في قوله: ﴿وَيَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِينُ﴾⟪24:25⟫ والإرادة منا تقتضي نزوع النفس إلى الشيء مع الحكم بأنه ينبغي أن يفعل وأن لا يفعل وإذا وصف الباري تعالى، فلا يصح أن يكون فيه النزاع ، إذ هو منزه عن ذلك، والاختيار أخص من الإرادة، فإن فيه مع الإرادة دلالة من اللفظ على تفضيل أحد الشيئين على الآخر، والإيمان ههنا: الاعتقاد الصادر عن العلم وإن كان في التعارف يقتضي مع الاعتقاد قولا وعملا بحسب مقتضاه والكفر ههنا: الاعتقاد الكاذب عن تخمين، ومعنى الآية: أن الكفار لما سمعوا النبي - صلى الله عليه وسلم - وقد تلا عليهم قوله: ﴿مَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ﴾⟪29:41⟫ وقوله ﴿وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـٔٗا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ﴾⟪22:73⟫ قالوا: لا يستحي ربك عن ذكر الذباب والعنكبوت؟ فأنزل الله تعالى ذلك - تنبيها - أن الاعتبار بالحكمة لا بصغر الجثة وكبرها،\nإن قيل: من حق مطابقة قوله [تعالى]: ﴿فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ﴾⟪2:26⟫ أي يقول: (وأما الذين كفروا فلا يعلمون)؟ قيل: لما كان الإيمان صادرا عن العلم، والعلم يقتضي سكون النفس وطمأنينة القلب، وذلك لا يقتضي مراجعة ومساءلة ذكر مقتضاه ولما كان الكفر منبع الجهل التام وتمام الجهل والاعتراض على الحق على\n⟦1:130⟧\nسبيل الإنكار، نبه بإنكارهم لما لا يعرفونه على تمام جهلهم وقوله: ﴿يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ﴾⟪2:26⟫ -[قد تقدم] الكلام في الإضلال والهداية، فأما الفاسق: فهو الخارج عن حجر الإيمان من قولهم: \" فسق الرطب عن قشرة \"، وكل كفر فسق، وليس كل فسق كفرا، وأكثر ما يقال الفاسق لمن التزم فسق حكم الإسلام وأقر به أو ببعضه ثم أخل به، وإذا قيل للكافر الأصلي فاسق، فلأنه أخل بحكم ما ألزمه العقل واقتضاه الفطرة، وللفاسق في انحلاله عن الإسلام ثلاث درجات: التغابي، والانهماك والجحود فبالتغابي: يرتكب بعض الذنوب مع استقباحه من نفسه، وبالانهاك: يرتكبها غير مبال بها، وبالجحود: يرتكبها مستصوبا لها.\n[والكبير والكثير يتقاربان، إلا أن الكبير والكثير أكثر ما يقال في أخر الشيء المتصل] فالكثير في الأعداد والمعدودات المنفصلة:\nإن قيل: كيف قال: ﴿يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ﴾⟪2:26⟫ والكثير والقليل إنما يقالان في شيئين يعتبر أحدهما بالآخر، والناس إذا فرقوا فرقتين فحكمت على إحديهما بالكثير، فالأحرى لا محالة قليلة، فكيف جعلهما كثيرين؟ قيل: إن ذلك باعتبارين، فقوله: ﴿يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ﴾⟪2:26⟫ يعني من حيث العدد، ﴿وَيَهۡدِي بِهِۦ كَثِيرٗاۚ﴾⟪2:26⟫ يعني من حيث الفضل والشرف.\nوعلى هذا قول الشاعر:\n\" قليل إذا عدوا كثير إذا شدوا \"\nأو يحكم عليهما بالكثرة - اعتبارا بالإضافة إلى غيرهما -.\n⟦1:131⟧"}, {"a": [27], "v": 1, "p": 131, "ev": 1, "ep": 133, "sid": 132, "t": "قوله تعالى:\n﴿ٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِۚ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ﴾⟪2:27⟫ الآية: (27) - سورة البقرة.\nالنقض: فسخ المبرم، وأصله في طاقات الحبل، والنكث: مثله، لكنه يقال في المتبلد كالأكسية، والأخبية، والعهد: كل أمر شأنه أن يراعي كاليمين، والمشاركة، والمبايعة، ويقال العهد للدار المراعاة بالرجوع إليها، والتاريخ المراعي، وللمطر المتعهد، والميثاق: اسم لما يقع به الوثاقة، والعهد المأمور بحفظه ضربان: عهد مأخوذ بالعقل، وعهد مأخوذ بالرسل، والمأخوذ بالرسل مبني على المأخوذ بالعقل، ولا يصح إلا بعده أو معه، وقد حملت الآية عليهما، وذلك هو المذكور في قوله: ﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾⟪7:172⟫ الآية، وفي قوله: ﴿وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ﴾⟪3:81⟫ وقد عظم الله تعالى أمر العهد وتوعد على الإخلال به في أي كثيرة، كقوله: ﴿فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفۡسِهِۦۖ﴾⟪48:10⟫ وقوله ﴿وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى﴾⟪33:7⟫ الآية وقال: ﴿فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ﴾ وقوله تعالى: ﴿إِنَّ ٱلَّذِينَ يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَيۡمَٰنِهِمۡ ثَمَنٗا قَلِيلًا﴾⟪3:77⟫ وأما ذمهم بقطع ما أمر الله به أن يوصل، فذم بقطع الخيرات وتعاطي السيئات، وذلك أن التقاطع بين الناس يحصل من رفض المحبة والعداية ورفضهما سبب كل فساد، فإن القوم إذا أحبوا وعدلوا تواصلوا، وإذا تواصلوا تعاونوا، وإذا تعاونوا عمروا وإذا عمروا عمروا وأمروا وبالعكس إذا تباغضوا وظلموا تدابروا وإذا تدابروا تخاذلوا وإذا تخاذلوا، لم يعمل بعضهم لبعض\n⟦1:132⟧\nفهلكوا ولهذا قال عليه السلام:\n(لا تقاطعوا، ولا تدابروا، وكونوا عباد الله إخوانا كما أمركم الله) وقال: (المؤمن مألف، ولا خير فيمن لا يؤلف ولا يألف)، ولذلك حثنا على الاجتماعات في الجماعات والجمعات، لكون ذلك سببا للألفة، بل لذلك عظم الله تعالى المنة على المؤمنين بإيقاع الألفة بين المؤمنين، فقال تعالى: ﴿لَوۡ أَنفَقۡتَ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ﴾⟪8:63⟫ وقال: ﴿وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ﴾⟪3:103⟫ وليس ذلك في الإنسان فقط، بل لولا أن الله تعالى الف بين الأركان المتضادة، لما استقام العالم، ولذلك قال عليه السلام: \" بالعدل قامت السماوات والأرض \" ومتى تصور هذه الجملة، علم أن الآية في نهاية الذم\n⟦1:133⟧\nلهم، وقول قتادة: \" إنه أمر بصلة الأرحام \"، وقول غيره: \" إنه ذم لهم بقطعهم النبي - صلى الله عليه وسلم - إشارة منهم إلى أبعاض ما يقتضيه عموم الآية، والخاسر في خسر إحدى المقتنيات الثلاثة من المال والبدن والعقل، وكما أن الفاسق بالقول المجمل على ثلاث طبقات بعضها فوق بعض، فكذلك ناقضوا العهد على ثلاث طبقات: ناقض عهده في أوامره المفروضة، وناقض عهده في أوامر النافلة، وناقض عهده في أركان الدين، وذلك أعظم الثلاثة، وكذلك قاطعو ما أمر الله به أن يوصل، قاطع لبعض ما يشير إليه عقله تابعا لهواه، وقاطع لبعض ما يأمر به العلم وبنوه، وقاطع للعصمة بينه وبين الله، وكذلك الخاسر: خاسر ماله في ابتغائه غير الدار الآخرة، وخاسر بدنه في غير خدمة الله، وخاسر عقله في إهماله عن اقتباس ما يفيده الحياة الأبدية، وذلك أعظم الخسران المنبأ عنه بقوله تعالى: ﴿قُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ أَعۡمَٰلًا﴾⟪18:103⟫ وقوله تعالى: ﴿إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ﴾.\nفلكل منزلة من الفسق منزلة من نقض العهد، ومنزلة من القطع، ومنزلة من الخسران تلازمه، فالأول في كل ذلك مخطئ، والثاني فاسق، والثالث كافر، ثم منزل كل واحد منهم يتفاوت."}, {"a": [28], "v": 1, "p": 134, "ev": 1, "ep": 135, "sid": 135, "t": "وقوله - عز وجل - ﴿كَيۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَٰتٗا فَأَحۡيَٰكُمۡۖ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ﴾⟪2:28⟫ الآية: (28) - سورة البقرة.\nكيف: ههنا استخبار لا استفهام، والفرق بينهما أن الاستخبار قد يكون تنبيها للمخاطب وتوبيخا ولا يقتضي جهل المستخبر، والاستفهام بخلاف ذلك، فكل استفهام استخبار، وليس كل استخبار استفهاما، والحياة: يستعمل على أوجه ، يقال للقوة النامية في النبات والحيوان حياة: ومنه قيل نبات حي إذا كان ناميا، وعلى ذلك قوله تعالى: ﴿ٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ﴾⟪57:17⟫ وقوله عز وجل: ﴿وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ﴾⟪50:11⟫ والثاني: للقوة الحساسة الحاسة، وبه سمي الحيوان حيوانا، والثالث: للقوة المختصة بالإنسان من العقل والعلم والإيمان، وذلك لكونها سببا للحياة الأبدية، وعلى ذلك قوله تعالى: ﴿أَوَمَن كَانَ مَيۡتٗا﴾⟪6:122⟫ وقوله: ﴿ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ﴾⟪8:24⟫ وعلى نحوه قوله:\nوقد أسمعت لو ناديت حيا ...\nولكن لا حياة لمن تنادي\nوالموت: يستعمل في فقد كل واحد مما تقدم، وأما وصف الباري - جل ثناؤه - بالحي، فليس يتصور منه مقابله الموت، فإنه تعالى الدائم الباقي الذي به حياة كل حي، ومعنى الآية: قبل \" كنتم أمواتا \" أي: ترابا ونطفة، فأحياكم، بأن أنشأكم وخلقكم ثم يميتكم الموت المعروف، ثم يحييكم يوم ينفخ\n⟦1:135⟧\nفي الصور، \" ثم إليه ترجعون أي تردون إلى دار الثواب والعقاب، وذلك نحو قوله: ﴿رَبَّنَآ أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ﴾⟪40:11⟫ ونبه بمثل هذه الآيات على أن القادر على الابداء، قادر على الإعادة، كما قال: ﴿وَهُوَ أَهۡوَنُ عَلَيۡهِۚ﴾⟪30:27⟫ وقال بعض أهل الحقائق: الآية خطاب للمؤمنين، ولا على الإنكار بل على تعظيم المنة عليهم وتبعيد الكفر منهم بعد تحققهم بالإيمان، فقد قيل: \" ما رجع من رجع إلا من الطريق، أي: لا ينكر الله أحد بعد تخصصه بالمعرفة الحقيقية، وإنما يرتد ويتشكك من لم يبلغها، فمحال أن يصير العارف جاهلا، وليس بمحال أن يصير الجاهل عالما، فيقول: \" كنتم أمواتا \" أي جهالا فأحياكم بما أفادكم من العقل ورشحكم له من العلم، كما قال: ﴿أَوَمَن كَانَ مَيۡتٗا فَأَحۡيَيۡنَٰهُ﴾⟪6:122⟫ وهذا أعظم أعجوبة، وأولى بالاعتبار به والتنبيه عليه لمن ألقى السمع وهو شهيد، ثم قال: (يميتكم) الموت المعروف الذي لا يجب أن يتكادكم ثم يحييكم الحياة الحقيقية، ثم تثابون الثواب الذي لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر."}, {"a": [29], "v": 1, "p": 135, "ev": 1, "ep": 137, "sid": 136, "t": "قوله - عز وجل -:\n﴿هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَٰوَٰتٖۚ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ﴾⟪2:29⟫ الآية (29) - سورة البقرة.\nالاستواء: طلب السواء، أي المساواة، وسمي وسط الشيء سواء، لتساوي مساحة الجوانب كلها إليه، وقيل للعدل سواء لكونه وسطأ للظلم والانظلام،\nإن قيل: قوله تعالى: ﴿خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا﴾⟪2:29⟫ يقتضي أن كل ما في الأرض خلق لأجل الإنسان، والانتفاع به، ومعلوم أن في الأرض كثيرا مما لا ينفع للإنسان فيه، بل فيه المضار كالحيات والعقارب، (والسموم) والأشرار من الناس، قيل: الأشياء الضارة في الظاهر لكل نوع منها خاصة فيها نفع للإنسان أو نفع لما فيه نفع للإنسان،\n⟦1:136⟧\nفأجزاء العالم إذا تأملتها إما أن تكون قرارا للإنسان، أو غذاء له، أو غذاء لما هو غذاء له، أو دواء له، أو ما ينتفع به نفعا نا على وجه.\nوذلك بين في أنواع الأشياء وأجناسها.\nفأما نفع جزيئاتها في أن يقال: ما نفع هذه الحية بعينها فلا سبيل لنا إليه، وأجزاء العالم شيء ضار بالإضلاق، وإنما الضار بالاعتبار إلى جزيئاته،\nإن قيل: كيف ذكر ههنا أنه خلق ما في الأرض قبل السماء وقد قال: ﴿وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ﴾⟪79:30⟫، معلوم أن ما في الأرض محال وجوده قبل وجودها؟ قيل: قد ذكر في هذا جوابان: أحدهما: أنه تعالى خلق جوهر الأرض، ثم دحاها وبسطها بعد خلق السماء، والثاني: أنه خلق السماء بعد خلق الأرض ووجودها، وإنما وقعت الشبهة من قوله: ﴿وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ﴾⟪79:30⟫، لأن بعض الناس تصور له من جهة القرآن قوله: ﴿بَعۡدِ ذَٰلِكَ﴾ ظرف لقوله: (دحاها) واعتبر في (بعد) الزمان وليس كذلك، فإن تقدير الآية: ﴿وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ﴾⟪79:30⟫، ثم قال: ﴿دَحَىٰهَآ ۝ أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا﴾⟪79:30-31⟫.\nكقوله: ﴿ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ﴾⟪79:27⟫ ثم قال: ﴿بَنَىٰهَا ۝ رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا﴾⟪79:27-28⟫، وليس \" بناها \" وصفا للسماء، بل تقديره: (أم السماء أشد خلقا)، ثم استوؤنف فقيل: بناها - تنبيها أن من قدر على ذلك [فهو على] إعادتكم قادر، ثم قال: ﴿وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ﴾⟪79:30⟫ أي الأرض بعد السماء أشد خلقا من إعادة خلقكم، وذلك لأن السماء بما فيها من عجائب الصنعة أعظم خلقا من الأرض، ثم الأرض أعظم من الإنسان، وليس يريد بقوله بعد التوقيت، وإنما يريد الترتيب في الشرف والرفعة،\nفإن قيل: ولم نصب الأرض ولم يرفعها كما رفع السماء؟\n⟦1:137⟧\nقيل: لأن القول استحبار، وقوله: \" والأرض \" ليس بداخل في الاستخبار، لأنه لو كان استخبارا لقال: أم الأرض، لكنه استأنفه، فأضمر له فعلا نحو: ﴿يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّٰلِمِينَ أَعَدَّ لَهُمۡ﴾⟪76:31⟫، ذلك الفعل ما دل عليه (أنتم أشد) من التعرف، وقوله: ﴿ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ﴾⟪2:29⟫ فالاستواء وإن كان في الأصل للإقبال الدال على الانتقال، فقد يراد به التوفر على إصلاح الشيء، وهو المراد ههنا، وعلى ذلك الاتيان في نحو قوله: ﴿فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ﴾⟪59:2⟫، ويكون اللفظ متجوزا [به] ههنا، قال بعضهم: معناه: استولى وقال الحسن: أقبل على خلقه، وقال ابن عباس - رضي الله عنهما - استوى أمره عليه، وقيل معنى: (سواهن) أي تحرى السواء، أي العدالة وذلك لما جعل فيها من التركيب المتعادل المشار إليه بقول النبي - صلى الله عليه وسلم -: \" بالعدل قامت السماوات \"،\nإن قيل: لم ذكر السماء ثم قال: (فسواهن).\nقيل: لما عنى بالسماء السموات رد الضمير إلى المعنى، ومجاز ذلك أن الأسماء على ضربين: اسم موضوع لأجزاء الرجل والمرأة متشابهة، نحو: الدم، واللحم، والماء، والأرض، واسم موضوع لأجزاء غير متشابهة، نحو: اليد، والرجل، فما كان من الأول، فإنه يقع على بعضه اسم كله، فلا فرق بين أن يذكر بلفظ واحد، أو بلفظ الجمع.\nوالسماء من هذا الباب، لأنه يقال لأقطاع اللحم لحم، ولكل قطعة منها منفصلة كانت أو متصلة لحم كذلك السماء، والله أعلم."}, {"a": [30], "v": 1, "p": 138, "ev": 1, "ep": 141, "sid": 139, "t": "قوله - عز وجل -: ﴿وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ﴾⟪2:30⟫ الآية (30) - سورة البقرة.\nإذ: يتعلق بمضمر في موضع المفعول به، لأن تقديره: اذكر لا أذكر فيه، وقول أبي عبيد: إن \" إذ \" في مثل هذه المواضع زائدة، فإنه تقصير منه في النظر ، والملك أصله \" ملاك \" مقلوبا عن مالك، والألوك: الرسالة المحفوظة في الفم من \" ألك الفرس اللجام \"، إذ لاكه، وروي أن الملائكة على أضرب خواص يتميزن تمييزا مبانيا في الفضيلة، منهم وأدون ألو أجنحة، وجماعة يقال لهم الجن، وهم أقرب إلى النسا، وقد يقال للصالح من الناس \" ملك \" على ذلك قوله تعالى: ﴿إِنۡ هَٰذَآ إِلَّا مَلَكٞ كَرِيمٞ﴾⟪12:31⟫\nوقال الشاعر:\nفلست لإ نسى ولكن لملاك\nوالخليفة والخلف يتقاربان من قولك: خلف فلان فلانا إذا قام مقامه، والخلف والسلف يتناقضان كخلف وقدام،\nفإن قيل: ما وجه استخلاف الله تعالى، والخلافة إنما تكون للنيابة عن الغري؟ إما لغيبته أو موته أو عجزه، وذلك لا يجوز على الله تعالى قيل: بل قد يكون على غير ذلك، وهو أن يستخلف المستخلف غيره امتحانا للمستخلف، أو تهذيبا له، أو يستخلفه لقصور المستخلف عليع من قبول التأثير من المستخلف لا لعجز المستخلف وذلك ظاهر في الأشياء المهينة والطبيعية، فإن السلطان\n⟦1:139⟧\nجعل الوزير بينه وبين رعيته، إذ هو يقبلون من الواعظ ماله قرب إلى قبولهم منه، وكذا الواعظ جعل بين العامة والحكماء، فإن العامة لا يقبلونه من الحكيم، وليس ذلك لعجز الحكيم، بل لعجز العامة عن القبول منه، وعلى هذا اللحم والعظم لما تباعد ما بينهما عجز العظم عن قبول الغذاء من اللحم، فجعل الله تعالى بحكمته بينهما الغضاريف التي بينهما، ولها مناسبة إليهما لتأخذ ذلك من اللحم وتعطيه العظم، وكذلك جعل تعالى الرسل بين الملك الذي هو من قبله تعالى وبين العباد لفضل قوة أعطاهو ليأخذوا منه الحكمة ويوصلوها إلى الناس، وبهذا الوجه قال تعالى: ﴿وَلَوۡ جَعَلۡنَٰهُ مَلَكٗا لَّجَعَلۡنَٰهُ رَجُلٗا﴾⟪6:9⟫، والخليفة يقال للواحد والجمع، وهاهنا [هو] جمع، فإن الخليفة لم يرد به آدم عليه السلام فقط، بل أريد هو وصالحو أولاده، فهم خلفاؤه وحزبه لقوله تعالى: ﴿حِزۡبَ ٱللَّهِ﴾، وأنصاره لقوله: ﴿وَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ﴾⟪57:25⟫، وعباده لقوله: ﴿وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ﴾⟪51:56⟫، وعمارة في الأرض لقوله: ﴿وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾⟪11:61⟫، والمقصود واحد بهذه العبارات وإن اختلفت بحسب الاعتبارات، وقيل سماهم خليفة لكونهم بعد جان سكنوا الأرض، فإن كل من تولى شيئا بعد آخر يقال له هو خليفة، وعلى ذلك قوله تعالى: ﴿وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ﴾⟪7:69⟫ وقوله تعال: ﴿خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ﴾⟪7:74⟫، وأما السفك، والسبك، والسفح، والسن، والشن، والصب، فمتقاربة، وبينهما فروق، فالصب: أعم من هذه الألفاظ، السفك: يقال في الدم والدمع، والسبك يقال للجواهر المذابة، والسفح: في الصب من أعلى، كسفح الجبل، وعنه استعير السفاح، والشن للصب عن القربة ونحوها، والسن يقاربه، لكن استعير السن في إماهة الحديد، وعنه بني المس والشن\n⟦1:140⟧\nللصب عن القربة ونحوها، والسن يقاربه، لكن استعير السن في إماهة الحديد، وعنه بني المس والشن استعمل في الغارة، وفي لبس الدرع، وذلك لتشبيه الدرع بالماء، وأجزاء الكتيبة بأجزاء السيل، وأما التسبيح فأصله السبح أي سرعة الذهاب في الماء، واستعير لمر النجوم في الفلك، ولجري الفرس، قال تعالى: ﴿إِنَّ لَكَ فِي ٱلنَّهَارِ سَبۡحٗا طَوِيلٗا﴾⟪73:7⟫ أي: سعة ذهاب.\nوسبحته عن كذا: أي نزهته، وتسبيح الله: تنزيهه بالقول والحكم و \" سبحان \" مصدر، ككفران، وجعل السبحة للتسبيح، وسمى الصلاة بها لكونها تسبيحا والحرزات: سمى سبحة، ومعنى: (نسبح بحمدك) أي: نسبحك والحمد لك، أو نسبحك بأن نحمدك والتقديس: التطهير، وقوله: ﴿وَنُقَدِّسُ لَكَۖ﴾⟪2:30⟫ قيل معناه نطهر أنفسنا لك - إشارة إلى نحو قوله: ﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلۡمُتَطَهِّرِينَ﴾⟪2:222⟫ وليس ذلك إظهارا للمنة، بل هو على حسب ما نقول مجتهد محب أن يفوض صاحبه إليه خدمة ما، فيقول: أتستعين بغيري وأنا مجتهد في خدمتك؟ وعلى ذلك قولهم: ﴿وَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ ۝ وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ﴾⟪37:165-166⟫ ولي قوله: ﴿إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ﴾⟪2:30⟫ على سبيل الاستشارة، فالاستشار استمداد علم من المستشار، والله تعالى منزه عن ذلك، وإنما ذلك إعلام، كإعلامه إيانا كثيرا من الكائنات لمصلحة ما،\nإن قيل: فمن أين حكمت الملائكة على الإنسان بالإفساد في الأرض وسفك الدماء، وذلك إما ادعاء علم الغيب أو الحكم بالظن والتخمين، وهم منزهون عن ذلك؟ قيل: قد قيل إنهم قاسوهم على من كان يسكن الأرض قبل من الجان، فأفسدوا فيها، وقيل: وهو أصح أن الله تعالى كان قد أخبرهم بذلك، لكن لم يقص علينا فيما حكى عنهم تنبيها عليه بما ذكر في الجواب وذلك عادة القرآن في كثير من الأقاصيص المذكورة، كقوله تعالى في قصو يوسف عليه السلام: ﴿أَنَا۠ أُنَبِّئُكُم بِتَأۡوِيلِهِۦ فَأَرۡسِلُونِ ۝ يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا﴾⟪12:45-46⟫ وقولهم: ﴿أَتَجۡعَلُ فِيهَا﴾⟪2:30⟫ ليس بانكار إنما هو استخبار مجرد ليعرفهم ما تسكن نفوسهم إليه ويرشدهم إلى ما يزيل شبهتهم وليسألوا عن ذلك ألا وقد أذن لهم في السؤال\n⟦1:141⟧\nأما جملة وتفصيلا، إن قيل كيف أدخل عليهم الشبهة حتى سألوا عن ذلك واستنكروه؟ قيل: إن الله تعالى لما خلق الإنسان جسمانيا وروحانيا وجعله مركبا من قوى ثلاث، قوة شهوية، وقوة غضبية وقوة ملكية فبقوته الشهوية يفسد في الأرض، وبقوته الغضبية يسفك الدماء متى لم تكونا مهذبتين ويتولى خلافة الله تعالى بقوته الملكية التي هي العقل، وعلى ذلك دل النبي - عليه السلام - بقوله \" لما خلق الله العقل، قال له: أقبل، فأقبل، ثم قال له: أدبر، فأدبر، ثم قال: وعزتي وجلالي ما خلقت خلقا أكرم علي منك، بك أخذ، وبك أعطي \"، فلما سمعت الملائكة أن الإنسان مركب من هذا التركيب ورأوا القوة التي بها تصلح لخلافته القوة التي خصوا بها ونظروا إلى رذيلة القوتين الأخريين ولم يعرفوا فضيلتهما استنكروا فراجعوا الله تعالى وقالوا: أما العبادة التي هي التسبيح والتقديس المختصة بالقوة الملكية، فنحن نقيمها، فما معنى الإنسان المركب تركيبا لا ينفك من فساد وقتل؟ فقال تعالى في جوابهم: ﴿إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ﴾⟪2:30⟫ فعرض ولم يصرح ها هنا ليريهم فضيلة الإنسان وما خصوا به من العلم والعمل اللذين يفضلان الملك عنهما عيانا ومشاهدة والإجمال في هذه الآية بقوله: ﴿إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ﴾⟪2:30⟫ هم المبين بما بعده من الآية التي [تليها] .."}, {"a": [31, 32, 33], "v": 1, "p": 142, "ev": 1, "ep": 148, "sid": 143, "t": "﴿وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ ۝ قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ۝ قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ﴾⟪2:31-33⟫\nالآيات: (31، 32، 33) سورة البقرة.\nالإنباء: إخبار فيه إعلام، وهو متضمن لهما ولذلك كل إنباء أخبار، وليس كل إخبار إنباء، وكل نبأ علما وليس كل علم نبأ ولكونه متضمنا لهما، ومشتملا عليهما أجري مجرى كل واحد منهما فقيل أنبأته بكذا كقولك أخبرته وأنبأته بكذا، كقولك أعلمته كذا، ولا يقال: \" نبأ \" إلا لكل خبر يقتضي العلم كالمتواتر، وخبر الله تعالى، وخبر الأنبياء [عليهم السلام] وما جرى مجراها، وسمى النبي لكونه منبئا بما تسكن نفسه إليه، ومنبأ بما سكن المؤمنون إليه فهو أصح من أن يكون فعيلا بمعنى فاعل وبمعنى مفعول، أما بمعنى الفاعل، فلقوله: ﴿نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ﴾⟪15:49⟫ وقوله ﴿أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ﴾⟪3:15⟫ وأما بمعنى المفعول فلقوله: ﴿نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ﴾⟪66:3⟫ وشرح هذه الآية لابد أن يبين فيه كيف كان تعليم الله آدم الأسماء، وهل فيه دلالة على أن اللغات توقيف أو أوائلها إصطلاح؟ وأنه هل علمه الأسماء دون المعاني؟ أو علمه إياها جميعا؟ وما في ذلك مما تنبه الملائكة على خطئهم فيما توهموه وقالوه حتى رجعوا عن دعواهم واعتقادهم وأذعنوا للاستسلام؟ فنقول وبالله التوفيق: إن الناس اختلفوا في اللغات، فذهب بعض المتكلمين إلى أن أوائلها اصطلاح، والباقي يصح أن يكون توقيفا، واستدل على ذلك بأنه لا سبيل إلى معرفة مراد الله تعالى إلا بالخطاب، ولا يصح أن يكون العلم بمراده ضرورة والعلم بذاته مكتسبا لأن ذلك مؤد إلى أن تعلمه ضرورة أن العلم بمراده فرع على العلم بذاته فلا يصح أن يكون العلم الخفي ضروريا والجلي\n⟦1:143⟧\nمكتسبا، وذلك فاسد، هذا ما قاله، والصحيح - إن شاء الله - ما ذهب إليه الجمهور إنه توقيف وقيل: الدلالة على المسألة إن تعليم الله عباده على أي وجه يكون، فذلك يسهل الكلام في المسألة، والقول في ذلك - إن شاء الله تعالى - قد أشار إلى ذلك بقوله تعالى: «وما كان لبشر أن يكلمه الله إلا وحيا أو من وراء حجاب أو يرسل رسولا فيوحي بإذنه ما يشاء إنه علي حكيم» فذكر أن مكالمته للبشر على أحد هذه الوجوه الثلاثة، وأشرفها ما كان بإرسال رسول يرى ذاته، ويسمع كلامه كحال النبي - صلى الله عليه وسلم - مع جبرائيل - عليه السلام - والثاني: ما كان بإلقاء الكلام في السمع من غير رؤية، كحال موسى - عليه السلام - في ابتداء أمره، والثالث: ما كان بوحي والوحي - ههنا - مخصوص بالإلقاء في الروع، والإلهام، والتسخير، والمنامات فتعليم الله تعالى آدم [عليه السلام] الأسماء على أحد هذه الوجوه، ومحال أن يكون الاصطلاح على الألفاظ متقدما على التعليم فإن الاصطلاح لابد له من كلام يتواطؤون عليه، وذلك يؤدي إلى أن لا يكون اصطلاح ولا لغة،\nفإن قيل: فما ينكر أن يتواضعوا بإشارات وتصويت، فإن الأخرس يقدر على ذلك، وله مخارج الحروف، لأنا نجد الذين لا يتكلمون يفهمون ويفهمون ولا لغة لهم! قيل: الإشارات يفهم عنها بالاستدلال كسائر الاستدلالات التي لو توهمنا الكلام مرتفعا لصح حصوله وليس للأخرس إلا الاستدلال فقط، ولا قدرة له على الألفاظ يؤلفها، وإنما صوته كصوت الطفل الذي لم يتلقن الألفاظ واللغة إنما تكون لغة بحصول تركيب المفردات الثلاث ولو كان إلى ذلك سبيل من غير تعليم، لكان من شرط البكم أن يتواضعوا فيما بينهم كلاما لأن آفة البكم من السمع، وإنما عجز عن الكلام لعجزه عن التلقن بالسمع، فثبت أن ابتداء تعليم الكلام لا يكون إلا من معلم، وذلك قد كان من الله تعالى لآدم بأحد هذه الوجوه المتقدمة\nإن قيل: كيف علمه الأسامي كلها وقد علمنا أنه ما من زمن إلا وبنوه يضعون\n⟦1:144⟧\nأسامي لمعاني وأعيان إما مخترعة وإما منقولا إليها عن غيرها؟ قيل: قد قال بعض الناس: \" إن كل تلك بجزئيات علمها الله تعالى آدم - عليه السلام - وإن ظهر في بعض الأزمنة من بعض أهله والصحيح: أن العلم في الحقيقة يتعلق بمعرفة الأصول المشتملة على الفروع، والمعاني الكلية المنطوية على الأجزاء كمعرفة جوهر الإنسان والفرس والقوانين التي يعرف بها حقيقة الشيء مثل أصول الضرب في الحساب، وأحوال الأبعاد والمقادير في الهندسة، والأصول المبني عليها المسائل الكثيرة في الفقه والكلام والنحو.\nفأما معرفة الجزئيات متعرية عن الأصول، فليس بعلم، ولا يقال للعارف بها عالم على الإطلاق، وإنما هو في معرفتها محاك محاكاة الببغاء للألفاظ وإذا كان كذلك، فتعليم الله تعالى آدم الأسماء كلها إعلامه القوانين والأصول المشتملة على الجزئيات والفروع وقد علم أن تعليم الكليات أعظم في الأعجوبة وأشبه بالأمور الإلاهية من تعليمنا الصبي الحرف بعد الحرف وقوله: ﴿ٱلۡأَسۡمَآءَ كُلَّهَا﴾⟪2:31⟫ أراد بها الألفاظ والمعاني ومفرداتها، ومركباتها وحقائقها وذوات الأشياء في أنفسها، وبيان ذلك أن الاسم يستعمل على ضربين: أحدهما بحسب الوضع الاصطلاحي، وذلك هو للمخبر عنه، نحو: \" رجل وفرس \" والثاني: بحسب الوضع الأول، وذلك يقال للأنواع الثلاثة التي هي المخبر عنه، والخبر والرابط بينهما، وهي المعبر عنها بالاسم والفعل والحرف، وهذا هو المراد ههنا، فإنه - تعالى - لم يرد بقوله: ﴿وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا﴾⟪2:31⟫ تعليمه رجلا وفرسا دون ذهب وخرج ومن وعن ولا يعرف الإنسان الاسم فيكون عارفا بمسماه إذا عرض عليه إلا أن يعرف المسمى، ألا ترى أنا لو علمناه أسامي [بالهندية] أو بلغة مجهولة، ولم يعرف صورة ما له تلك الأسماء لم يكن عارفا بها إذا شاهدناها وكنا عارفين بأصوات مجردة، فثبت أن معرفة الاسم لا تحصل إلا بمعرفة المسمى في نفسه وحصول صورته في الضمير، ثم المعلومات قد تكون جواهر وأعراضا من\n⟦1:145⟧\nكميات وكيفيات، وإضافات وسائر ذلك من الأعراض، ويجعل للشيء الواحد أسامي بحسب هذه النظرات، فلابد أن يكون الإنسان عارفا بهذه المعاني مجتمعة ومفترقة حتى يكون عارفا بالأسماء التي يجعل [ذلك] لها بحسبها، مثال ذلك: أنه يقال للشخص الواحد \" فلان \" - اعتبارا بلقبه، و \" رجل \" اعتبارا بالآلة المولدة، [و \" ابن \" اعتبارا بوالده، و \" أب \" اعتبارا بولده] و \" أخ \" اعتبارا بمن ضمه وإياه نسب، وقرشي وأصبهاني اعتبارا بقبيلته وبلده إلى غير ذلك من الأسماء [التي يكثر تعدادها، فإذا حقيقة قوله: ﴿وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا﴾⟪2:31⟫ متضمنة لما ذكرناه،\nفإن قيل: فأي شيء في تعليم آدم الأسماء من تنبيه الملائكة على ما سئلوا عنه؟ قيل: إن الله تعالى لما خلق الإنسان من أمشاج مختلفة وقوى متفاوته وجعله جسمانيا روحانيا، وحصل له بحسب القوى المختلفة معارف مختلفة وأفعال متفاوته، فإن له بحسب الحواس الخمس معارفا خمسا، وبحسب العقل معارف معقولة وبحسب الوهم والخيال معارف موهومة متخيلة وحصل له بحسب التراكيب البدنية وبسائطها أفعال متباينة ومهن متفاوتة كالتجارة، والصياغة، وسائر الصناعات.\nوجل ذلك معدوم في الملك لعدم كثافة الجسم المركب من الأمشاج، ولاستغنائها عن ذلك، فبين الله تعالى بتعليمه آدم - عليه السلام - هذه الأسماء كلها والمعاني وعرضها على الملائكة، وأنبأ آدم - عليه السلام - بها وبحقائقها.\nومعرفة تعاطي الصناعات المختصة بالإنسان عجز الملائكة، وأن الإنسان مستصلح لعلوم وأعمال ليس للملك سبيل إليها [بوجه] فإن المحسوس لا يدركه محسوسا إلا ذو الحاسة، والمهن لا يتعاطاها إلا من ركب تركيب الإنسان من القوى المتفاوته التي منها القوتان اللتان كانوا يرونهما مفسدتين.\nأعني القوة\n⟦1:146⟧\nالشهوية والقوة والغضبية، ونبههم أن ذلك وإن كان فيه مفسدة ما، ففيها مصالح كثيرة، وأن الخلافة التي رشح لها الإنسان في الأرض لا يصلح لها إلا هذا التركيب، فحينئذ قال لهم: ﴿أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ﴾⟪2:33⟫.\nإن قيل: ما وجه قوله: ﴿إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ﴾⟪2:33⟫ وهل كان لهم في ذلك التشكك حتى احتاجوا إلى أن يقال لهم ذلك؟ قيل له: ليس مخرج هذا الكلام على الوجه الذي توهمته، بل هو تنبيه لهم بما عملوه مجملا على ما اشتبه عليهم مفصلا، وتقدير ذلك: كأنه قيل: ﴿إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ﴾⟪2:33⟫ ومن علم غيب السماوات والأرض علم ما تبدون وما تكتمون.\nومن علم ذلك علم ما لا تعلمون.\nإن قيل: فما [تلك] الفضائل التي اختص الإنسان بها واستصلح لها مما لم يكن للملائكة؟ قيل له: إن ذلك هو تعاطي العفة التي هي مختصة بالقوة الشهوية، والنجدة المختصة بالقوة الغضبية، والإنصاف في المعاملات، وسياسة الإنسان نفسه، ومجاهدة هواه وسياسة ذويه وأبناء جنسه، فإن كل ذلك فضائل ليست إلا للإنسان المختص بقوته الشهوية والغضبية، فأما الملك المعرى عن مقاسات عارية \" بطنه وفرجه \" فليس بمحتاج إلى سياسة البدن وسياسة أبناء جنسه في مراعاة ذلك منهم، [وهذا ظاهر]\nإن قيل: في وجه قوله: ﴿أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ﴾⟪2:31⟫ وذلك تكليف لهم ما لا تعلمون وتكليف إيراد ما لا يعلم تكليف ما لا يطاق، وما وجه قوله تعالى: ﴿إِن كُنتُمۡ صَٰدِقِينَ﴾⟪2:31⟫ والصدق إنما يتعلق بالخبر، وهم إنما استخبروا ولم يخبروا فكيف يصح أن يصدقوا أو يكذبوا قيل: أما قوله: ﴿أَنۢبِـُٔونِي﴾⟪2:31⟫ فليس بتكليف وإنما هو تنبيه على عجزهم عن الخلافة التي رشح الإنسان لها، وقد علم أن لفظة \" افعل \" تجيء على أوجه، منها: التبكيف والتعجيز، وقوله: ﴿إِن كُنتُمۡ صَٰدِقِينَ﴾⟪2:31⟫ فالصدق وإن كان لا يدخل الاستخبار والأمر والنهي بالقصد\n⟦1:147⟧\nالأول، ومن حيث مقتضى اللفظ، فإنه قد يدخلها بالقصد الثاني، ومن حيث المعاني فإن السائل إذا قال مستفهما: أزيد في الدار؟ أو قال: أعطني شيئا، فكأنه بالأول ينبه على جهله يكون زيد في الدار، وبالثاني على حاجة وافتقار، فمن هذا الوجه صح أن يقال: \" هو صادق أو كاذب \" على أن هذا حكم على قولهم: ﴿مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ﴾⟪2:30⟫ فإنهم استفهموا بقولهم: ﴿أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ﴾⟪2:30⟫ ويصح أن يكون ذلك راجعا إلى قوله: ﴿وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ﴾⟪2:30⟫ تنبيها لهم على أنه ليس كل تسبيح وتقديس بما يقولونه، بل من التسبيحات والتقديسات ما يصلح له غيركم، وهو ما تقدم ذكره.\nإن قيل: ما وجه قوله: ﴿سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ﴾⟪2:32⟫ وهو عالم بما علمهم وعالم بأن لا علم لهم إلا ما علمهم؟ قيل: القصد بذلك إظهار أن ليس سؤالهم على وجه الاعتراض، بل على سبيل الاستفادة وإظهار العجز، وأنه قد بدا لهم ما كان خفي عليهم من فضيلة الإنسان وإظهار الشكر لنعمته وتعظيم منته بما عرفهم وفيه تنبيه على استعمال [حسن] الأدب عند سؤال المعلم بتفويض العلم إليه وتنبيه على أعظم التواضع، فقد قيل لبعض الحكماء : ما أعظم التواضح؟ فقال: الاعتراف بالجهل للعالم، وفيه تنبيه على العلم بما جهلوه، وذلك إحدى فضيلتي الإنسان، وقال بعض المحققين: الافتخار مدرجة للسقوط، انظر كيف اضطر الله الملائكة لما قالوا: ﴿وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ﴾⟪2:30⟫ إلى أن اعترفوا بعدم العلم، فمن استكثر لله طاعة واستكبر له خدمة فالجهل موطنه واستدل بعضهم بهذه الآية على أن العلم أفضل من العبادة، فإن الملائكة أذعنوا لآدم [عليه السلام] لما أفيد من العلم، والحكيم أصله لمن له الفعل المحكم، لكن لما يصح حصول الففعل المحكم إلا بالعلم [المتقن] صارت الحكمة متناولة للعلم والعمل معا.\nفالحكمة منتهى العلم.\nوالعلم مبدأ الحكمة، ولا يتم أحدهما إلا بالآخر.\nفلهذا جمع بينهما.\nوقدم \" العليم \" [هاهنا] على \" الحكيم \" فقال: ﴿إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ﴾⟪2:32⟫.\n⟦1:148⟧"}, {"a": [34], "v": 1, "p": 148, "ev": 1, "ep": 152, "sid": 149, "t": "قوله - عز وجل -:\n﴿وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ﴾⟪2:34⟫\nالآبة: (34) سورو البقرة.\nالخضوع والخشوع والخنوع والسجود والركوع تتقارب، وبينهما فروق، فالخضوع ضراعة بالقلب، والخشوع بالجوارح، ولذلك قيل: إذا تواضع القلب خشعت الجوارح، وقال تعالى: ﴿ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ﴾⟪23:2⟫، وقال: ﴿وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ﴾⟪20:108⟫، والخشوع ضراعة لمن دونه رغبة في عرض في يده، وكذلك أكثر ما يجئ في الدم، والركوع تذلل مع التطأطؤ.\nوالسجود مع خفض الرأس.\nوسجود الملائكة إن أريد به المتعارف في الشرع.\nفليس بعبادة لآدم -[عليه السلام]، فعبادة غير الله تعالى لا تجوز بوجة، وإن كان على حسب المتعارف للخدمة، فقد قيل: إن ذلك كان مباحا قبل شرعنا، وعلى ذلك ما روي في قصة يوسف - عليه السلام - ﴿وَخَرُّواْ لَهُۥ سُجَّدٗاۖ﴾⟪12:100⟫، وقد قيل: أريد به التذلل كقوله تعالى: يسجد له من في السماوات ومن في الأرض}.\nوقول الشاعر:\nترى الأكم فيه سجدا للحوافر\nوإبليس: لفظة أعجمية، فلا يصح أن تكون مشتقة من العربية.\n⟦1:149⟧\nوقول ابن عباس - رضي الله عنهما - \" إبليس أبلس من رحمة الله، إلى ذكر الحكم لا إلى معنى اللفظ، ويصح أن يجعل \" إبليس \" مشتقا منه بعد الانتقال إلى العربية، وعلى ذلك كثير من الأعلام أعجميا كان أو عربيا يتصورون منه معنى ما، ويشتقون منه نحو قولهم: \" تفرعن فلان \" إذا فعل فعل فرعون في العتو وتشيطن إذا فعل فعل الشيطان، وتمرد: فعل فعل المردة، فعلى هذا تصوروا من إبليس يأسه من رحمة الله، فاشتقوا منه، فقالوا \" أبلس فلان \" أي: \" أجرى مجرى إبليس \" في يأسه من الرحمة وإبعاده من الخير، وقوله: ﴿فَإِذَا هُم مُّبۡلِسُونَ﴾⟪6:44⟫ أي: يائسون من الخير يأس إبليس منه، وأيضا قد تتطابق لغة العرب والعجم في لفظة نحو: \" أيوب وإسحف \"، فإنهمت قد يكونان فيعولا، وإفعالا من أب وسحق، ويكونان أعجمين، وآدم - عليه السلام - قيل: سمي بذلك لكونه مخلوقا من أديم الأرض على ما روي أن الله تعالى قبض قبضة من جميع الأرض - سهلها وجبلها، فخلق منها آدم - عليه السلام - فلذلك يأتي بنوه أخيافا، قال قطرب: لا يكون من ديم الأرض، لأنه لو كان كذلك، لانصرف نحو: \" طابع، وخاتم \" وطابق وليس كما قال، فإن \" آدم \" أفعل منه، وأصله: أأدم، فقلبت الهمزة ألفا، وقيل: هو أفعل من الأدمة: أي اختلاط البياض بالسواد، \" وأدمت بين الشيئين \"، أي خلطت ومنه: الأدم، وطعام مأدوم أي مخلوط، وقال: وسمي بذلك، لأنه خلق من الأركان الأربعة، ومن الأمزجة المتفاوتة والقوى المتباينة، والإباء: الامتناع من الشيء مع\n⟦1:150⟧\nالإرادة، فكل إباء امتناع، وليس كل امتناع إباء، قال الله تعالى: ﴿وَيَأۡبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ﴾⟪9:32⟫ وقيل: \" أبيت اللعن \"، وهي أبوأ، إذا تسلط عليها داء، فصار مانعا لها من الشراب والتكبر: أن يرى الإنسان نفسه أكبر من غيره فضلا، والاستكبار: طلب ذلك بالشبع والكبر، والتيه، والبغي، والزهو، والاستطالة، والخيلاء، والصلف تتقارب، وبينها فرق، فالتيه: التحير في معرفة قدر النفس، والبغي: طلب منزلة فوق ما يستحقه، والزهو: سرعة الحكم لنفسه بالفضل، من: \" زهاه كذى \" إذا استحقه، والاستطالة: إظهار طول، أي فضل على الغير.\nوالخيلاء: ظن بالنفس كاذب، من قولهم: خلت، والصلف: قلة التلفت إلى الغير من قولهم: صلف: إذا اشتكى صليفه، واعتبارا بهذا المعنى قال الشاعر:\nإن الكريم من تلفت حوله ...\nفإن اللئيم الطرف أقود\n* واختلف في إبليس هل كان من الملائكة؟ فقال قوم: كان منهم، بدلالة استثنائه من الملائكة المأمورين للسجود لآدم، وقال قوم: لم يكن منهم اعتبارا بقوله تعالى: ﴿إِلَّآ إِبۡلِيسَ كَانَ مِنَ ٱلۡجِنِّ﴾⟪18:50⟫، وروى عن ابن عباس - رضي الله عنهما - أن الملائكةعلى ثلاثة أضرب على ما تقدم آنفا، وضرب منهم يقال لهم الجن، ومنهم إبليس، ولهم توالد، ولهذا قال: ﴿أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوۡلِيَآءَ مِن دُونِي وَهُمۡ لَكُمۡ عَدُوُّۢۚ﴾⟪18:50⟫، وقيل: إن الجن كانوا مأمورين مع الملائكة بالسجود له، لكن لم يحتج إلى ذكرهم، فالسلطان إذا أمر أماثل رعيته بالخضوع لإنسان، فمعلوم أن أصاغرهم مأمورين بذلك، ألا ترى أن\n⟦1:151⟧\nقوله تعالى لموسى ﴿ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ﴾ معلوم أنه لم يبعث، إليه وحده، وبعض الناس اعتبر لفظ \" كان \"، وروي أن إبليس كان من الجن الذين سكنوا الأرض قبل آدم، وحاربهم الملائكة، وسبوا إبليس، فصار بالحكم من الملائكة، فمولى القوم منهم، وبالنسبة من الجن، فصار بصدق عليه القولان، ويجوز أن يكون عنى أنه كان من الجن فعلا، ومن الملائكة نوعا، وباعتبار الفعل قال تعالى: ﴿وَكَانَ مِنَ ٱلۡكَٰفِرِينَ﴾⟪2:34⟫\nإن قيل: كيف يصح أن يكون من الملائكة نوعا والله قد وصفهم بأنهم ﴿لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ﴾⟪66:6⟫؟ قيل: إن ذلك في وصف خزنة جهنم، وليس كون بعضهم على هذه الصفة مقتضيا أن يكون كلهم كذلك، و ﴿كَانَ مِنَ ٱلۡجِنِّ﴾⟪18:50⟫: قيل معناه: صار ههنا، وليس ذلك بشيء، فإن (كان) استعمل (ههنا) على أحد وجهين: إما لاعتبار وقت العصيان بوقت الاختبار، ويكون بالإضافة إليه ماضيا فيجب أن يقال: كان، وإما أنه قال: ﴿وَكَانَ مِنَ ٱلۡكَٰفِرِينَ﴾⟪2:34⟫ - تبيها أن ما تقدم من طاعته غير معتد به، وأن حكمه من قبل حكم الكافرين، فمن شرط الطاعة أن لا تحبط ومن حكم الإيمان أن يمتد ويتصل،\nإن قيل: كيف أمر الملائكة بالسجود لآدم ومنزلتهم فوق منزلته بدلالة أن إبليس مناه أن يكون إياهم بقوله: ﴿مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ﴾⟪7:20⟫ وبعيد أن يؤمر الفاضل بالتخضع للمفضل؟ قيل: الخضوع لآدم كان خضوعا لله تعالى من أجل الائتمار له فيما أمرهم به، وظاهر في العادات أن التذلل لخادم كبير خضوع لذلك الكبير، وأيضا: فإن الإنسان في باب الفضائل التي ذكرناها آنفا أفضل من الملك وإن كان الملك أفضل منه من وجوه أخر، والشيئان قد يكون كل واحد منهما أفضل من الآخر من وجه ووجه، وإنما المنكران بفضل كل واحد منها الآخر من وجه واحد، وفي الآية تنبيه على وجوب الائتمار لمن له الخلق والأمر، ومجانبة عصيانه، وارتكاب التكبر والحسد، وإنها قد يفضيان براكبهما إلى الكفر، كما روى في الخبر: \" أن أول ما عصي به الله في السماء والأرض الكبر والحسد \" وحث على ترك الدخول في سره والاعتراض على حكمه.\n⟦1:152⟧"}, {"a": [35], "v": 1, "p": 152, "ev": 1, "ep": 156, "sid": 153, "t": "قوله - عز وجل -:\n﴿وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ﴾⟪2:35⟫ الآية: (35) - سورة البقرة.\nقيل: ما الفرق بين أن يقال: افعل أنت وقومك كذا وبين أن يقال: افعلوا كذا، قيل: الأول تنبيه أن المقصود هو المخاطب، وغيره تبع له، وأنه لولاه لما كانوا مأمورين بذلك، وعلى نحوه: ﴿قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ﴾⟪20:49⟫ وليس كذلك إذا قال: افعلوا، وقال بعضهم: إنما قال: اسكن فاستعمل السكن تنبيها أنه يعرض النقل، عنها وأنه لا يجب أن يركن إليها.\nإن قيل: ما الفرق بين الإرادة والمشيئة؟ قيل: الإرادة قد تكون بحسب القوة التسخيرية، والفكرية والحسية ولذلك تستعمل في الجماد، نحو: ﴿جِدَارٗا يُرِيدُ أَن يَنقَضَّ﴾⟪18:77⟫ وفي الحيوان وفي العقلاء والمشيئة لا تكون إلا مع اختيار ولذلك لا يقال إلا للعالم والمتفكر، وقوله تعالى: ﴿وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ﴾⟪2:35⟫ فالقصد بالنهي عن قرب الشيء تأكيد للحظر والمبالغة في النهي، وذاك أن القرب من الشيء مقتض الألفة، والألفة داعية للمحبة، ومحبة الشيء كما قيل: \" حبك الشيء يعمي ويصم، والعمى عن القبيح والصم عن النهي عنهما الموقعان فيه، والسبب الداعي إلى الشر منهي عنه، كما أن السبب الداعي إلى الخير مأمور به، وعلى ذلك قال - عليه السلام -: (العينان تزنيان) لما كان النظر داعيا إلى الألفة، والألفة إلى المحبة، وذلك\n⟦1:153⟧\nمقتض لارتكابه، فصار النظر مبدأ للزنا، وعلى هذا قال: ﴿وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ﴾⟪17:32⟫، و ﴿وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ﴾ ﴿لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ﴾⟪4:43⟫ وعلى هذا قال في الخمر: ﴿فَٱجۡتَنِبُوهُ﴾⟪5:90⟫ وبهذا النظر قال عليه الصلاة والسلام: \" الحلال بين، والحرام بين، وبين ذلك أمور مشتبهة، وسأضرب مثلا، إن لله حما، وإن حمى الله محارمه، ومن رتع حول الحما أوشك أن يقع فيه \".\nوالشجرة: قيل: كانت الحنطة، وقيل: الكرم، وقيل: التين، وقوله: (فتكونا): الأظهر: أنه جواب النهي، وقد قيل: يصح أن يكون عطفا، لأنك تقول: \" لا تجب والدك فتعص ربك كما تقول: فتعصي ربك، والظلم في الحقيقة: الإخلال بما يقتضيه داعيا الله: \" العقل والشرع \" وهو الخروج عن الحظر ولهذا قيل: هو وضع الشيء في غير موضعه، وقد تقدم أن الظلم ضربان: ظلم النفس، وظلم الغير، وظلم الغير لا ينفك من ظلم النفس، وظلم النفس قد ينفك من ظلم الغير، ولأجل أن الظلم خروج عن الحق، وأن الحق يجري مجرى النقطة من الدائرة، ومجرى القرطاس من الهدف، صار من تعداه يصح أن يقال: \" هو ظالم \" وإن كان بين الظالم والظالم بون ولذلك قد يطلق \" الظالم \" على من ارتكب صغيرة وعلى من ارتكب كبيرة، إن قيل كيف جاز أن ينهي عن الشجرة ثم يتناولها وقد أنكرتم أن يرتكب الأنبياء الكبائر؟ قيل: قد أجيب عن ذلك بأن آدم [عليه السلام] أشير له إلى شجرة، فقيل له: \" لا تقربا هذه الشجرة \" وأريد به الجنس لا العين نحو ما روي أن النبي - عليه\n⟦1:154⟧\nالسلام - خرج وفي إحدى يديه ذهب، وفي الأخرى حرير، فقال: \" هذا حرام على ذكور أمتي حل لإناثها.\nولم يرد به العين، وإنما أراد به الجنس، فحمل آدم متأولا الإشارة إلى العين دون الجنس، فوقع عليه السهو من هذا الوجه، وقيل: أنه حمل النهي على الندب دون الحتم، ونسي الوعيد المقرون به، ولذلك قال: ﴿وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ﴾⟪20:115⟫ أي: \" نسي الوعيد \".\nواختلف في الجنة التي أسكنها آدم - عليه السلام - فقال بعض المتكلمين: كان بستانا جعله الله تعالى له امتحانا ولم يكن جنة المأوى فإن تلك لم تخلق بعد، إذ هي للخلود، وقد ثبت أن الله تعالى يفني الأشياء كلها حتى لا يبقى إلا وجهه ولو كانت مخلوقة الآن لم يصح أن يخص بهذه الصفة، وقال أكثر الناس: كانت جنة المأوى، وتسميتها بجنة الخلد اعتبارا بدوامها بعد أن يدخلها المثابون.\nوالشيء الواحد قد يسمى بأسماء كثيرة - اعتبارا بمعان متفاوته، ألا ترى إلى ما حكي عن الحسن أنه قال: \" خلقنا للأبد، ولكنا ننقل من دار إلى دار \" وذلك اعتبارا بحال الإعادة، ومن قال: لم تكن تلك جنة الخلد، لأنه لا تكليف في الجنة، وآدم [عليه السلام] كان مكلفا، [فقد قيل في جوابه: إنما لا يكون دار التكليف في الآخرة، ولا يمتنع أن يكون في وقت دار تكليف، ولا يكون في وقت كذلك، كما أن الإنسان يكون] مكلفا في وقت دون وقت، وقال بعض الناس: \" إن الله تعالى لما خلق الإنسان لاستخلافه في أرضه واستعماره فيها كما قال: ﴿إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ﴾⟪2:30⟫ ﴿وَيَسۡتَخۡلِفَكُمۡ فِي ٱلۡأَرۡضِ﴾⟪7:129⟫ وقال ﴿وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾⟪11:61⟫ وأراد أن يوصله بذلك إلى جنة المأوى وعلم بسابق علمه أنه لسوء تدبيره\n⟦1:155⟧\nقد يختار العاجل الخسيس على الأجل النفيس لعجلته كما وصفه بقوله تعالى: ﴿وَكَانَ ٱلۡإِنسَٰنُ عَجُولٗا﴾⟪17:11⟫ وأنه قد تتبع هواه كما قال: ﴿وَٱتَّبَعُوٓاْ أَهۡوَآءَهُم﴾ وعلم ما يكون منه أدخله الجنة ليعرف النعيم الذي أعد له عيانا، فيكون إليه أشوق، ويتذوق طعم المخالفة فيكون منها أخوف، فمعلوم من حال الإنسان أن المحنة تهذبه، والاشتياق إلى ما عاينه من الخيرات يرغبه، فصار ما جرى [على آدم] من الأحوال من تمام النعمة عليه، والله أعلم بوجوه المصالح، وفي الآية حث على قبول قول من هو أعلم منك وتحري نصحك والمصلحة، وإن الإنسان إذا حفظ في دنياه قرناءه المتصلة به من قواه الشهوية والغضبية، وقرناءه المتصلة به من قواه الشهوية والغضبية وقرناءه المنفصلة عنه من أهله وولده وساس نفسه وأهله، ورعى من الله أوامره، وتجنب زواجره كان في الجنة عاجلا وأجلا، وإلا صار معاونة عليه ومنافعه راجعة بالمضرة إليه، كما قال تعالى: ﴿فَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾⟪9:55⟫.\n⟦1:156⟧"}];
